'use client'

import * as React from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'

/**
 * The 5 foundation documents, in the order the repo's pipeline writes them.
 * `brand-profile.md` is the source every other file derives from; `voice.md` is the
 * exception — voice-builder derives it from real writing samples, never from the profile.
 */
const FOUNDATION_FILES = [
  'brand-profile.md',
  'voice.md',
  'audience.md',
  'social-strategy.md',
  'content-pillars.md',
] as const

/** Files that a batch run can derive from brand-profile.md. voice.md is deliberately excluded. */
const BATCH_FILES = ['audience.md', 'social-strategy.md', 'content-pillars.md']

const FILE_HINT: Record<string, string> = {
  'brand-profile.md': 'Identitas, voice, guardrail, channel. Sumber semua file lain.',
  'voice.md': 'Di-derive dari 3-5 contoh tulisan asli, bukan dari brand profile. Tidak bisa 1-klik.',
  'audience.md': 'Bisa di-derive dari brand-profile.',
  'social-strategy.md': 'Bisa di-derive dari brand-profile.',
  'content-pillars.md': 'Bisa di-derive dari brand-profile. Kalender butuh file ini.',
}

type Stage = { key: string; label: string; description: string | null; sort_order: number }
type PipelineSkill = { id: string; name: string; description: string | null; stage: string | null }
type ClientSkill = { skill_id: string; status: string; notes: string | null }

interface FoundationPanelProps {
  clientId: string
  stages?: Stage[]
  skills?: PipelineSkill[]
  clientSkills?: ClientSkill[]
  /** Paths of files already written for this client (client_files.path). */
  files?: string[]
  provider?: { id: string; name: string; model: string | null } | null
  connectedChannels?: number
  onAction: (skillId: string) => void
}

function statusVariant(status: string) {
  if (status === 'ada' || status === 'terhubung') return 'ghost' as const
  if (status === 'gagal') return 'destructive' as const
  if (status === 'generate-ready') return 'ghost' as const
  if (status === 'loading') return 'secondary' as const
  return 'secondary' as const
}

export function FoundationPanel({
  clientId, stages = [], skills = [], clientSkills = [], files = [],
  provider = null, connectedChannels = 0, onAction,
}: FoundationPanelProps) {
  const [voiceOpen, setVoiceOpen] = React.useState(false)
  const [voiceSamples, setVoiceSamples] = React.useState('')
  const [voiceSaving, setVoiceSaving] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [batchState, setBatchState] = React.useState<Record<string, 'loading' | 'ada' | 'gagal'>>({})
  const [batchError, setBatchError] = React.useState<string | null>(null)

  const hasFile = (path: string) => files.includes(path) || batchState[path] === 'ada'

  const voiceSampleBlocks = voiceSamples.trim()
    ? voiceSamples.trim().split(/\n\s*\n/).filter((b) => b.trim().length > 0)
    : []
  const voiceValid = voiceSampleBlocks.length >= 3 && voiceSamples.trim().length >= 100

  const statusFor = (path: string): string => {
    if (batchState[path]) return batchState[path]
    if (hasFile(path)) return 'ada'
    // generate-ready: transient state saat dialog voice terbuka dan sampel valid
    if (path === 'voice.md' && voiceOpen && voiceValid) return 'generate-ready'
    return path === 'voice.md' ? 'butuh sampel' : 'belum'
  }

  const handleVoiceGenerate = async () => {
    if (!voiceValid || voiceSaving) return
    setVoiceSaving(true)
    try {
      const res = await fetch(`/api/admin/clients/${clientId}/foundation/voice`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ samples: voiceSampleBlocks }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        toast.error(data?.error ?? `HTTP ${res.status}`)
        return
      }
      toast.success('voice.md berhasil dibuat dari sampel tulisan.')
      setVoiceSamples('')
      setVoiceOpen(false)
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Gagal membuat voice.md')
    } finally {
      setVoiceSaving(false)
    }
  }

  const foundationReady = FOUNDATION_FILES.filter(hasFile).length
  const statusBySkill = React.useMemo(
    () => Object.fromEntries(clientSkills.map((c) => [c.skill_id, c.status])),
    [clientSkills]
  )
  const sortedStages = [...stages].sort((a, b) => a.sort_order - b.sort_order)
  const brandProfileReady = hasFile('brand-profile.md')

  const handleGenerate = async () => {
    if (!brandProfileReady || busy) return
    setBusy(true)
    setBatchError(null)
    setBatchState(Object.fromEntries(BATCH_FILES.map((p) => [p, 'loading' as const])))
    try {
      const res = await fetch(`/api/admin/clients/${clientId}/foundation/batch`, { method: 'POST' })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setBatchError(data?.error ?? `HTTP ${res.status}`)
        setBatchState({})
        return
      }
      const next: Record<string, 'ada' | 'gagal'> = {}
      for (const f of (data?.files ?? []) as Array<{ path: string; status: string }>) {
        next[f.path] = f.status === 'ada' ? 'ada' : 'gagal'
      }
      setBatchState((prev) => ({ ...prev, ...next }))
      if (data?.errors?.length) setBatchError(data.errors.join('; '))
    } catch (e) {
      setBatchError((e as Error)?.message ?? 'Gagal menghubungi server')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* Voice builder dialog */}
      <Dialog open={voiceOpen} onOpenChange={setVoiceOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Buat Voice dari Sampel Tulisan</DialogTitle>
            <DialogDescription>
              Voice di-derive dari tulisan asli, bukan brand profile. Tempel 3-5 contoh tulisan
              asli klien (post, caption, artikel). Pisahkan antar sampel dengan baris kosong.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-2">
            <Label htmlFor="voice-samples">
              Contoh tulisan asli (3-5 sampel, minimal 100 karakter total)
            </Label>
            <Textarea
              id="voice-samples"
              rows={10}
              placeholder={'Contoh caption Instagram 1\n\n#lorem ipsum dolor sit amet\n\nContoh caption Instagram 2\n\n...'}
              value={voiceSamples}
              onChange={(e) => setVoiceSamples(e.target.value)}
              disabled={voiceSaving}
            />
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span>{voiceSampleBlocks.length}/3 sampel terpisah</span>
              <span>{voiceSamples.trim().length}/100 karakter</span>
            </div>
          </div>

          <p className="text-xs text-muted-foreground">
            Aturan repo:{' '}
            <a
              href="https://github.com/social-media-skills/skills/blob/main/skills/voice-builder/SKILL.md"
              target="_blank"
              rel="noreferrer"
              className="underline underline-offset-3 hover:text-foreground"
            >
              voice-builder/SKILL.md
            </a>{' '}
            : voice harus dari sampel asli, jangan di-invent dari brand profile.
          </p>

          <DialogFooter>
            <Button
              variant="outline"
              className="h-11 sm:h-9"
              onClick={() => setVoiceOpen(false)}
              disabled={voiceSaving}
            >
              Batal
            </Button>
            <Button
              className="h-11 sm:h-9"
              onClick={handleVoiceGenerate}
              disabled={!voiceValid || voiceSaving}
              title={voiceValid ? undefined : 'Minimal 3 sampel terpisah dan 100 karakter total'}
            >
              {voiceSaving ? <Icons.spinner className="size-4 animate-spin" /> : null}
              {voiceSaving ? 'Membuat voice.md...' : 'Buat voice.md dari sampel'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Readiness strip */}
      <div className="flex flex-wrap gap-2">
        <div className="flex min-h-11 items-center gap-2 rounded-lg border bg-card px-3 text-sm">
          <span className={`size-2 rounded-full ${foundationReady === FOUNDATION_FILES.length ? 'bg-green-600' : 'bg-amber-500'}`} />
          {foundationReady} dari {FOUNDATION_FILES.length} file fondasi
        </div>
        <div className="flex min-h-11 items-center gap-2 rounded-lg border bg-card px-3 text-sm">
          <span className={`size-2 rounded-full ${connectedChannels > 0 ? 'bg-green-600' : 'bg-muted-foreground'}`} />
          {connectedChannels} channel terhubung
        </div>
        <div className="flex min-h-11 items-center gap-2 rounded-lg border bg-card px-3 text-sm">
          <span className="size-2 rounded-full bg-muted-foreground" />
          {provider ? `Provider: ${provider.name}${provider.model ? ` ${provider.model}` : ''}` : 'Provider belum diatur'}
        </div>
      </div>

      {/* Foundation files */}
      <Card>
        <CardHeader>
          <CardTitle>File fondasi</CardTitle>
          <CardDescription>
            Urutan repo: brand-profile dulu, baru sisanya. Skill lain baca file ini sebelum menulis.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-0">
          {FOUNDATION_FILES.map((file, i) => {
            const status = statusFor(file)
            const isBrandProfile = file === 'brand-profile.md'
            const isVoice = file === 'voice.md'
            return (
              <div
                key={file}
                className={`flex min-h-14 items-center justify-between gap-3 py-2.5 ${i > 0 ? 'border-t' : ''}`}
              >
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <code className="text-sm font-medium">{file}</code>
                    <Badge variant={statusVariant(status)}>{status}</Badge>
                  </div>
                  <p className="mt-0.5 text-xs text-muted-foreground">{FILE_HINT[file]}</p>
                </div>
                {isBrandProfile && (
                  <Button variant="outline" className="h-11 shrink-0 lg:h-8" onClick={() => onAction('brand-profile')}>
                    Edit brand profile
                  </Button>
                )}
                {isVoice && status !== 'ada' && (
                  <Button
                    variant="outline"
                    className="h-11 shrink-0 lg:h-8"
                    onClick={() => setVoiceOpen(true)}
                  >
                    Tambah sampel tulisan
                  </Button>
                )}
                {!isBrandProfile && !isVoice && (
                  <Badge variant="outline" className="shrink-0">ikut batch</Badge>
                )}
              </div>
            )
          })}

          {/* Batch generation — wires to /api/admin/clients/[id]/foundation/batch */}
          <div className="mt-3 rounded-lg border bg-muted/40 p-3">
            <p className="text-sm font-medium">Generate {BATCH_FILES.length} file fondasi</p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              {BATCH_FILES.join(' → ')}, berurutan. Tiap skill baca brand-profile. Berhenti kalau ada yang gagal.
            </p>
            <Button
              className="mt-3 h-11 w-full lg:h-8"
              onClick={handleGenerate}
              disabled={!brandProfileReady || busy}
            >
              {busy ? 'Generating…' : 'Generate dari brand profile'}
            </Button>
            {!brandProfileReady && (
              <p className="mt-2 text-xs text-destructive">
                brand-profile.md belum ada. Isi dulu sebelum generate.
              </p>
            )}
            {batchError && (
              <p className="mt-2 text-xs text-destructive">{batchError}</p>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'

interface Message {
  role: 'user' | 'assistant'
  content: string
}

interface SkillRef {
  id: string
  name: string
}

interface SkillChatProps {
  clientId: string
  skill: SkillRef | null
  providerId?: string
  onClose: () => void
  onSaved?: () => void
}

export function SkillChat({ clientId, skill, providerId, onClose, onSaved }: SkillChatProps) {
  const router = useRouter()
  const [messages, setMessages] = useState<Message[]>([])
  const [input, setInput] = useState('')
  const [busy, setBusy] = useState(false)
  const [err, setErr] = useState<string | null>(null)

  // Output states
  const [file, setFile] = useState<{ path: string; content: string } | null>(null)
  const [output, setOutput] = useState<{ title: string; content: string; stage: string } | null>(null)
  const [preview, setPreview] = useState<{ title: string; content: string } | null>(null)
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [editing, setEditing] = useState(false)

  const scrollRef = useRef<HTMLDivElement>(null)
  const started = useRef(false)

  // Auto-start interview
  useEffect(() => {
    if (skill && !started.current) {
      started.current = true
      send('Halo! Saya siap untuk memulai interview skill ' + skill.name)
    }
  }, [skill])

  // Scroll to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [messages, busy])

  const send = async (content: string) => {
    if (!skill || busy) return
    const newMessages: Message[] = [...messages, { role: 'user', content }]
    setMessages(newMessages)
    setInput('')
    setBusy(true)
    setErr(null)

    try {
      const res = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          skill_id: skill.id,
          provider_id: providerId,
          messages: newMessages,
        }),
      })

      const j = await res.json()
      if (!res.ok) throw new Error(j.error || 'Gagal menghubungi AI')

      setMessages([...newMessages, { role: 'assistant', content: j.reply }])

      if (j.file) {
        setFile(j.file)
        setSaved(false)
      }
      if (j.output) {
        setOutput(j.output)
        setSaved(false)
      }
      if (j.preview) {
        setPreview(j.preview)
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Terjadi kesalahan')
    } finally {
      setBusy(false)
    }
  }

  const saveToRepo = async () => {
    if (!file && !output) return
    setSaving(true)
    try {
      const endpoint = file ? `/api/admin/clients/${clientId}/files` : `/api/admin/clients/${clientId}/outputs`
      const body = file ? { path: file.path, content: file.content } : output

      const res = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      if (!res.ok) throw new Error('Gagal menyimpan')

      setSaved(true)
      toast.success(file ? 'File tersimpan ke repository' : 'Output tersimpan ke Hasil')
      if (onSaved) onSaved()
      router.refresh()
    } catch (e) {
      toast.error('Gagal menyimpan: ' + (e instanceof Error ? e.message : 'Error'))
    } finally {
      setSaving(false)
    }
  }

  if (!skill) return null

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onClose() }}>
      <DialogContent className="flex h-[90vh] max-w-[95vw] flex-col p-0 overflow-hidden sm:max-w-6xl">
        <div className="flex h-full flex-col md:flex-row">

          {/* LEFT PANEL: Chat Interview */}
          <div className="flex flex-col border-r bg-muted/10 md:w-[45%]">
            <DialogHeader className="border-b p-4">
              <div className="flex items-center gap-2">
                <div className="size-8 rounded-lg bg-brand-accent/10 text-brand-accent flex items-center justify-center">
                  <Icons.chat className="size-5" />
                </div>
                <div className="min-w-0">
                  <DialogTitle className="text-base truncate">{skill.name}</DialogTitle>
                  <DialogDescription className="text-[10px] uppercase tracking-wider font-semibold text-brand-accent">
                    Interview Fondasi AI
                  </DialogDescription>
                </div>
              </div>
            </DialogHeader>

            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-4 space-y-4"
            >
              {messages.length === 0 && !busy && (
                <div className="flex flex-col items-center justify-center h-full text-center p-6 text-muted-foreground">
                  <Icons.sparkles className="size-8 mb-2 opacity-20" />
                  <p className="text-xs italic">Menunggu respon pertama dari AI...</p>
                </div>
              )}

              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] rounded-2xl px-4 py-2.5 text-sm ${
                    m.role === 'user' 
                    ? 'bg-brand-accent text-white rounded-tr-none' 
                    : 'bg-white border shadow-sm rounded-tl-none text-foreground'
                  }`}>
                    {m.content}
                  </div>
                </div>
              ))}

              {busy && (
                <div className="flex justify-start">
                  <div className="bg-white border shadow-sm rounded-2xl rounded-tl-none px-4 py-2.5 flex items-center gap-2">
                    <Icons.spinner className="size-3.5 animate-spin text-brand-accent" />
                    <span className="text-xs text-muted-foreground">AI sedang mengetik...</span>
                  </div>
                </div>
              )}

              {err && (
                <div className="p-3 rounded-lg bg-destructive/10 border border-destructive/20 text-destructive text-xs">
                  {err}
                </div>
              )}
            </div>

            <div className="p-4 border-t bg-white">
              <div className="relative">
                <Textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault()
                      if (input.trim()) send(input.trim())
                    }
                  }}
                  placeholder="Tulis jawaban Anda di sini..."
                  className="min-h-[80px] resize-none pr-12 rounded-xl focus-visible:ring-brand-accent"
                />
                <Button 
                  size="icon" 
                  className="absolute bottom-2 right-2 size-8 rounded-lg bg-brand-accent hover:bg-brand-accent/90"
                  onClick={() => input.trim() && send(input.trim())}
                  disabled={busy || !input.trim()}
                >
                  <Icons.send className="size-4" />
                </Button>
              </div>
              <p className="mt-2 text-[10px] text-muted-foreground text-center">
                Tekan <strong>Enter</strong> untuk mengirim, <strong>Shift+Enter</strong> untuk baris baru.
              </p>
            </div>
          </div>

          {/* RIGHT PANEL: Live Document Preview */}
          <div className="flex flex-col flex-1 bg-white">
            <div className="flex items-center justify-between border-b px-6 py-4">
              <div className="flex items-center gap-2.5">
                <Icons.post className="size-4 text-muted-foreground" />
                <span className="text-sm font-semibold text-foreground">
                  {file ? file.path : output ? output.title : preview ? preview.title : 'Pratinjau Dokumen'}
                </span>
                {saved && (
                  <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium bg-green-50 text-green-700 border border-green-200">
                    <Icons.check className="size-3" /> Tersimpan
                  </span>
                )}
                {preview && !file && !output && (
                  <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200">
                    <Icons.spinner className="size-3 animate-spin" /> Draf Langsung
                  </span>
                )}
              </div>

              <div className="flex items-center gap-3">
                {(file || output) && (
                  <>
                    <Button 
                      variant="outline" 
                      size="sm" 
                      className="h-8 text-xs gap-1.5"
                      onClick={() => setEditing(!editing)}
                    >
                      <Icons.edit className="size-3" /> {editing ? 'Lihat Preview' : 'Edit Manual'}
                    </Button>
                    <Button 
                      size="sm" 
                      className="h-8 text-xs bg-brand-accent hover:bg-brand-accent/90 gap-1.5"
                      onClick={saveToRepo}
                      disabled={saving || saved}
                    >
                      {saving ? <Icons.spinner className="size-3 animate-spin" /> : <Icons.save className="size-3" />}
                      {saved ? 'Tersimpan' : 'Finalisasi & Simpan'}
                    </Button>
                  </>
                )}
                {/* Close button removed: Dialog handles closing via overlay/ESC or top-right X */}
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6 bg-muted/5">
              {!file && !output && !preview ? (
                <div className="flex flex-col items-center justify-center h-full text-center text-muted-foreground space-y-3">
                  <div className="size-16 rounded-full bg-muted/20 flex items-center justify-center">
                    <Icons.fileText className="size-8 opacity-20" />
                  </div>
                  <div className="max-w-xs">
                    <p className="text-sm font-medium text-foreground">Menunggu Dokumen</p>
                    <p className="text-xs">
                      Lanjutkan interview di sisi kiri. Begitu data cukup, AI akan menyusun dokumen draf di sini secara real-time.
                    </p>
                  </div>
                </div>
              ) : editing && (file || output) ? (
                <Textarea
                  value={file ? file.content : output?.content || ''}
                  onChange={(e) => {
                    if (file) setFile({ ...file, content: e.target.value })
                    else if (output) setOutput({ ...output, content: e.target.value })
                    setSaved(false)
                  }}
                  className="h-full min-h-[500px] font-mono text-xs leading-relaxed focus-visible:ring-brand-accent"
                />
              ) : (
                <div className="bg-white p-6 rounded-xl border shadow-sm min-h-full">
                  <pre className="whitespace-pre-wrap font-sans text-xs text-foreground leading-relaxed">
                    {file ? file.content : output?.content || preview?.content || ''}
                  </pre>
                </div>
              )}
            </div>
          </div>

        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useSuspenseQuery, useQueryClient } from '@tanstack/react-query'
import { deliverableDetailQueryOptions, deliverableKeys } from '@/features/deliverables/api/queries'
import { createClient } from '@/lib/supabase/client'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Separator } from '@/components/ui/separator'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from '@/components/ui/dialog'
import { StatusBadge, TypeBadge } from '@/components/deliverable/status-badge'
import { CommentSection } from '@/components/deliverable/comment-section'
import { toast } from 'sonner'
import { Icons } from '@/components/icons'
import Link from 'next/link'

interface Comment {
  id: string
  content: string
  created_at: string
  author_name: string
  author_role: 'admin' | 'client'
}

interface DeliverableDetail extends Deliverable {
  clients?: { name: string; contact_email: string | null } | null
}

export default function DeliverableDetailPage({ deliverableId }: { deliverableId: string }) {
  const router = useRouter()

  const queryClient = useQueryClient()
  const { data: deliverable } = useSuspenseQuery(deliverableDetailQueryOptions(deliverableId))
  const [comments, setComments] = useState<Comment[]>([])
  const [loading, setLoading] = useState(true)
  const [sending, setSending] = useState(false)
  const [editing, setEditing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(false)
  const [confirmPublish, setConfirmPublish] = useState(false)
  const [publishing, setPublishing] = useState(false)
  const [publishMsg, setPublishMsg] = useState<{ ok: boolean; text: string } | null>(null)
  const [form, setForm] = useState({ title: deliverable?.title ?? '', content_md: deliverable?.content_md ?? '', external_link: deliverable?.external_link ?? '' })
  const supabase = createClient()

  const loadDeliverable = useCallback(async () => {
    setLoading(true)
    const { data: commentsData } = await supabase
      .from('deliverable_comments')
      .select('id, content, created_at, author_name, author_role')
      .eq('deliverable_id', deliverableId)
      .order('created_at', { ascending: true })

    if (commentsData) setComments(commentsData as unknown as Comment[])
    setLoading(false)
  }, [deliverableId, supabase])

  useEffect(() => { loadDeliverable() }, [loadDeliverable])

  // Realtime: refresh comments when a new one arrives (T027)
  useEffect(() => {
    const channel = supabase
      .channel(`comments-${deliverableId}`)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'comments', filter: `deliverable_id=eq.${deliverableId}` },
        () => { loadDeliverable() }
      )
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [deliverableId, supabase, loadDeliverable])

  const handleSend = async () => {
    if (!deliverable || sending) return
    setSending(true)
    try {
      const res = await fetch(`/api/admin/deliverables/${deliverableId}/send`, { method: 'POST' })
      if (res.ok) queryClient.invalidateQueries({ queryKey: deliverableKeys.detail(deliverableId) })
    } finally { setSending(false) }
  }

  const handlePublish = async () => {
    if (!deliverable || publishing) return
    setPublishing(true)
    setPublishMsg(null)
    try {
      const res = await fetch(`/api/admin/deliverables/${deliverableId}/publish`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ confirm: true }),
      })
      const j = await res.json()
      if (!res.ok) {
        setPublishMsg({ ok: false, text: j.error || 'Gagal publish' })
      } else {
        setPublishMsg({
          ok: true,
          text: `Post terkirim ke bridge (postId: ${j.postId ?? '-'}). Status delivery di cek di bridge.`,
        })
        setConfirmPublish(false)
        loadDeliverable()
      }
    } catch {
      setPublishMsg({ ok: false, text: 'Gagal menghubungi server' })
    } finally {
      setPublishing(false)
    }
  }

  const handleSave = async () => {
    if (!deliverable || saving) return
    setSaving(true)
    try {
      const res = await fetch(`/api/admin/deliverables/${deliverableId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      })
      const json = await res.json()
      if (res.ok) {
        queryClient.invalidateQueries({ queryKey: deliverableKeys.detail(deliverableId) })
        setEditing(false)
      } else {
        toast.error(json.error || 'Gagal menyimpan')
      }
    } finally { setSaving(false) }
  }

  const handleDelete = async () => {
    if (deleting) return
    setDeleting(true)
    try {
      const res = await fetch(`/api/admin/deliverables/${deliverableId}`, { method: 'DELETE' })
      const json = await res.json()
      if (res.ok) {
        router.push('/admin/deliverables')
        router.refresh()
      } else {
        toast.error(json.error || 'Gagal menghapus')
      }
    } finally {
      setDeleting(false)
      setConfirmDelete(false)
    }
  }

  const handleAddComment = async (content: string) => {
    const res = await fetch(`/api/admin/deliverables/${deliverableId}/comments`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content }),
    })
    if (res.ok) {
      const json = await res.json()
      if (json.comment) setComments((c) => [...c, json.comment as unknown as Comment])
    } else {
      const json = await res.json().catch(() => ({}))
      toast.error(json.error || 'Gagal menambah komentar')
    }
  }



  if (!deliverable) {
    return (
      <div className="mx-auto w-full max-w-4xl">
        <p className="text-muted-foreground">Deliverable tidak ditemukan.</p>
        <Button variant="outline" className="mt-4" onClick={() => router.push('/admin/deliverables')}>
          <Icons.arrowLeft className="mr-2 h-4 w-4" /> Kembali ke Daftar
        </Button>
      </div>
    )
  }

  const canSend = deliverable.status === 'draft'
  const canDelete = deliverable.status === 'draft'

  return (
    <div className="mx-auto w-full max-w-4xl">
      <div className="mb-6">
        <Link
          href="/admin/deliverables"
          className="mb-4 inline-flex items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <Icons.arrowLeft className="h-4 w-4" /> Kembali
        </Link>

        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0 flex-1">
            {editing ? (
              <Input
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                className="text-2xl font-bold"
                aria-label="Judul deliverable"
              />
            ) : (
              <h1 className="text-2xl font-bold tracking-tight">{deliverable.title}</h1>
            )}
            <div className="mt-2 flex items-center gap-3">
              <TypeBadge type={deliverable.type} />
              <StatusBadge status={deliverable.status} />
            </div>
          </div>

          <div className="flex shrink-0 gap-2">
            {editing ? (
              <>
                <Button variant="outline" onClick={() => setEditing(false)} disabled={saving}>
                  <Icons.close className="h-4 w-4" /> Batal
                </Button>
                <Button onClick={handleSave} disabled={saving}>
                  <Icons.save className="h-4 w-4" /> {saving ? 'Menyimpan...' : 'Simpan'}
                </Button>
              </>
            ) : (
              <>
                <Button variant="outline" onClick={() => setEditing(true)}>
                  <Icons.pencil className="h-4 w-4" /> Edit
                </Button>
                {canDelete && (
                  <Button variant="outline" onClick={() => setConfirmDelete(true)}>
                    <Icons.trash className="h-4 w-4" /> Hapus
                  </Button>
                )}
                {canSend && (
                  <Button onClick={handleSend} disabled={sending}>
                    <Icons.send className="h-4 w-4" /> {sending ? 'Mengirim...' : 'Kirim ke Client'}
                  </Button>
                )}
                {deliverable.status === 'approved' && (
                  <Button onClick={() => setConfirmPublish(true)} disabled={publishing}
                    className="bg-emerald-600 hover:bg-emerald-700 text-white"
                  >
                    <Icons.rocket className="h-4 w-4" /> {publishing ? 'Publishing...' : 'Publish'}
                  </Button>
                )}
              </>
            )}
          </div>
        </div>

        {(deliverable.status === 'approved' || deliverable.status === 'revision_requested') && !editing && (
          <p className="mt-3 rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
            Editing deliverable ini akan mengembalikannya ke status <strong>Draft</strong>.
          </p>
        )}
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="space-y-6 lg:col-span-2">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Konten</CardTitle>
            </CardHeader>
            <CardContent>
              {editing ? (
                <Textarea
                  value={form.content_md}
                  onChange={(e) => setForm({ ...form, content_md: e.target.value })}
                  className="min-h-[240px] font-mono text-sm"
                  placeholder="Isi konten (markdown)..."
                  aria-label="Isi konten markdown"
                />
              ) : deliverable.content_md ? (
                <pre className="whitespace-pre-wrap rounded-lg bg-muted p-4 font-mono text-sm">
                  {deliverable.content_md}
                </pre>
              ) : (
                <p className="italic text-muted-foreground">Tidak ada konten.</p>
              )}

              {editing ? (
                <div className="mt-4 space-y-2 border-t pt-4">
                  <Label htmlFor="external_link">Link Eksternal (opsional)</Label>
                  <Input
                    id="external_link"
                    value={form.external_link}
                    onChange={(e) => setForm({ ...form, external_link: e.target.value })}
                    placeholder="https://..."
                  />
                </div>
              ) : (
                deliverable.external_link && (
                  <div className="mt-4 border-t pt-4">
                    <a
                      href={deliverable.external_link}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-2 text-sm text-primary hover:underline"
                    >
                      <Icons.link className="h-4 w-4" /> Buka Link Eksternal
                    </a>
                  </div>
                )
              )}
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-6">
              <CommentSection
                deliverableId={deliverableId}
                comments={comments}
                onAddComment={handleAddComment}
              />
            </CardContent>
          </Card>
        </div>

        <div className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Informasi</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4 text-sm">
              <div className="flex items-center gap-3">
                <Icons.profile className="h-4 w-4 text-muted-foreground" />
                <div>
                  <p className="text-muted-foreground">Client</p>
                  <p className="font-medium">{deliverable.clients?.name || 'Belum ditentukan'}</p>
                  {deliverable.clients?.contact_email && (
                    <p className="text-xs text-muted-foreground">{deliverable.clients.contact_email}</p>
                  )}
                </div>
              </div>
              <Separator />
              <div className="flex items-center gap-3">
                <Icons.calendar className="h-4 w-4 text-muted-foreground" />
                <div>
                  <p className="text-muted-foreground">Dibuat</p>
                  <p className="font-medium">
                    {new Date(deliverable.created_at).toLocaleDateString('id-ID', {
                      day: 'numeric', month: 'long', year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <Icons.clock className="h-4 w-4 text-muted-foreground" />
                <div>
                  <p className="text-muted-foreground">Terakhir diubah</p>
                  <p className="font-medium">
                    {new Date(deliverable.updated_at).toLocaleDateString('id-ID', {
                      day: 'numeric', month: 'long', year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Status</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Icons.circleCheck className="h-4 w-4 text-primary" />
                  <span className="text-sm">Draft dibuat</span>
                </div>
                {deliverable.status !== 'draft' && (
                  <div className="flex items-center gap-2">
                    <Icons.send className="h-4 w-4 text-primary" />
                    <span className="text-sm">Terkirim ke client</span>
                  </div>
                )}
                {deliverable.status === 'approved' && (
                  <div className="flex items-center gap-2">
                    <Icons.circleCheck className="h-4 w-4 text-green-600" />
                    <span className="text-sm font-medium text-green-600">Disetujui</span>
                  </div>
                )}
                {deliverable.status === 'revision_requested' && (
                  <div className="flex items-center gap-2">
                    <Icons.messageSquare className="h-4 w-4 text-orange-600" />
                    <span className="text-sm font-medium text-orange-600">Revisi diminta</span>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      <Dialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Hapus deliverable?</DialogTitle>
            <DialogDescription>
              &ldquo;{deliverable.title}&rdquo; akan dihapus permanen. Tindakan ini tidak bisa dibatalkan.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2">
            <Button variant="outline" className="h-11 lg:h-8" onClick={() => setConfirmDelete(false)} disabled={deleting}>
              Batal
            </Button>
            <Button variant="destructive" className="h-11 lg:h-8" onClick={handleDelete} disabled={deleting}>
              <Icons.trash className="h-4 w-4" /> {deleting ? 'Menghapus...' : 'Hapus'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Publish confirmation dialog — structural gate (AGENTS.md ground truth 4). The admin sees
          exactly what will happen; the publish route refuses unless confirm: true is present. */}
      <Dialog open={confirmPublish} onOpenChange={(o) => { if (!o && !publishing) { setConfirmPublish(false); setPublishMsg(null) } }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Icons.rocket className="h-5 w-5 text-emerald-600" /> Publish deliverable?
            </DialogTitle>
            <DialogDescription>
              &ldquo;{deliverable.title}&rdquo; akan dipublikasikan ke semua akun social yang terhubung di bridge.
              Peringatan: ini akan tayang langsung dan tidak bisa dibatalkan dari sini.
            </DialogDescription>
          </DialogHeader>

          <div className="rounded-md border border-amber-500/40 bg-amber-500/10 p-3 text-sm">
            <p className="flex items-start gap-2 font-medium text-amber-700 dark:text-amber-400">
              <Icons.warning className="mt-0.5 h-4 w-4 shrink-0" /> Pastikan konten sudah benar
            </p>
            <p className="mt-1 text-xs text-amber-600/80">
              Publish tidak bisa dibatalkan dari dashboard. Hapus manual dari platform jika perlu.
            </p>
          </div>

          {publishMsg && (
            <p className={`text-sm ${publishMsg.ok ? 'text-green-600' : 'text-destructive'}`}>
              {publishMsg.text}
            </p>
          )}

          <DialogFooter className="gap-2">
            <Button variant="outline" className="h-11 lg:h-8" onClick={() => { setConfirmPublish(false); setPublishMsg(null) }} disabled={publishing}>
              Batal
            </Button>
            <Button className="h-11 lg:h-8 bg-emerald-600 hover:bg-emerald-700 text-white" onClick={handlePublish} disabled={publishing}>
              <Icons.rocket className="h-4 w-4" /> {publishing ? 'Publishing...' : 'Ya, Publish'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { KanbanBoard, type KanbanItem, type KanbanClient } from '@/components/production/kanban-board'
import { CalendarView, type ContentItem } from '@/components/production/calendar-view'
import { ContentFormModal } from '@/components/production/content-form-modal'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'

// Query key factory
const productionKeys = {
  all: ['production'] as const,
  items: () => productionKeys.all,
  clients: () => ['clients'],
}

// Fetch functions
async function fetchContentItems() {
  const res = await fetch('/api/admin/content-items')
  if (!res.ok) throw new Error('Failed to fetch content items')
  const data = await res.json()
  return data.contentItems ?? []
}

async function fetchClients() {
  const res = await fetch('/api/admin/clients')
  if (!res.ok) throw new Error('Failed to fetch clients')
  const data = await res.json()
  return data.clients ?? []
}

// Main production dashboard client component
export default function ProductionDashboard() {
  const [modalOpen, setModalOpen] = useState(false)
  const queryClient = useQueryClient()

  const { data: contentItems = [], isLoading: itemsLoading } = useQuery({
    queryKey: productionKeys.items(),
    queryFn: fetchContentItems,
    staleTime: 1000 * 60 * 2, // 2 min cache
  })

  const { data: clients = [], isLoading: clientsLoading } = useQuery({
    queryKey: productionKeys.clients(),
    queryFn: fetchClients,
    staleTime: 1000 * 60 * 5, // 5 min cache
  })

  const isLoading = itemsLoading || clientsLoading

  // Refetch query on modal close (after create/update/delete)
  useEffect(() => {
    if (!modalOpen) {
      queryClient.invalidateQueries({ queryKey: productionKeys.items() })
    }
  }, [modalOpen, queryClient])

  // Type casts
  const kanbanItems: KanbanItem[] = contentItems.map((item: any) => ({
    id: item.id,
    title: item.title,
    stage: item.stage ?? 'idea', // fallback for legacy data
    client_id: item.client_id,
    platform: item.platform,
  }))

  const kanbanClients: KanbanClient[] = clients.map((c: any) => ({
    id: c.id,
    name: c.name,
  }))

  const calendarItems: ContentItem[] = contentItems.map((item: any) => ({
    id: item.id,
    title: item.title,
    target_date: item.target_date,
  }))

  return (
    <Tabs defaultValue="kanban" className="flex h-full min-h-0 flex-col">
      <TabsList className="w-fit">
        <TabsTrigger value="kanban">Kanban Board</TabsTrigger>
        <TabsTrigger value="calendar">Calendar</TabsTrigger>
      </TabsList>

      {isLoading ? (
        <div className="flex flex-1 items-center justify-center">
          <Skeleton className="h-8 w-8 animate-spin rounded-full" />
        </div>
      ) : (
        <>
          <TabsContent value="kanban" className="flex-1 overflow-x-auto">
            <KanbanBoard initialItems={kanbanItems} clients={kanbanClients} />
          </TabsContent>
          <TabsContent value="calendar" className="flex-1">
            <CalendarView initialItems={calendarItems} />
          </TabsContent>
        </>
      )}

      {/* Create Modal */}
      <ContentFormModal
        clientId=""
        open={modalOpen}
        onOpenChange={setModalOpen}
        onSuccess={() => setModalOpen(false)}
      />
    </Tabs>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useSuspenseQuery, useQueryClient } from '@tanstack/react-query'
import { deliverableDetailQueryOptions, deliverableKeys } from '@/features/deliverables/api/queries'
import { createClient } from '@/lib/supabase/client'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Separator } from '@/components/ui/separator'
import { StatusBadge, TypeBadge } from '@/components/deliverable/status-badge'
import { CommentSection } from '@/components/deliverable/comment-section'
import { ApproveRevisionButtons } from '@/components/deliverable/approve-revision-buttons'
import { Button } from '@/components/ui/button'
import { Icons } from '@/components/icons'
import Link from 'next/link'

interface Comment {
  id: string
  content: string
  created_at: string
  author_name: string
  author_role: 'admin' | 'client'
}

export default function ClientDeliverableDetailPage({ deliverableId }: { deliverableId: string }) {
  
  const queryClient = useQueryClient()
  const { data: deliverable } = useSuspenseQuery(deliverableDetailQueryOptions(deliverableId))
  const [comments, setComments] = useState<Comment[]>([])
  const [loading, setLoading] = useState(true)
  const [downloading, setDownloading] = useState(false)
  const supabase = createClient()

  const loadDeliverable = useCallback(async () => {
    setLoading(true)
    const { data: commentsData } = await supabase
      .from('deliverable_comments')
      .select('id, content, created_at, author_name, author_role')
      .eq('deliverable_id', deliverableId)
      .order('created_at', { ascending: true })
    
    if (commentsData) {
      setComments(commentsData as unknown as Comment[])
    }
    
    setLoading(false)
  }, [deliverableId, supabase])

  useEffect(() => {
    loadDeliverable()
  }, [loadDeliverable])

  // Realtime: refresh comments when a new one arrives (T027)
  useEffect(() => {
    const channel = supabase
      .channel(`client-comments-${deliverableId}`)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'comments', filter: `deliverable_id=eq.${deliverableId}` },
        () => { loadDeliverable() }
      )
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [deliverableId, supabase, loadDeliverable])

  const handleApprove = async () => {
    const response = await fetch(`/api/client/deliverables/${deliverableId}/approve`, {
      method: 'POST',
    })
    
    if (response.ok && deliverable) {
      queryClient.invalidateQueries({ queryKey: deliverableKeys.detail(deliverableId) })
    }
  }

  const handleRevision = async (_deliverableId: string, reason: string) => {
    const response = await fetch(`/api/client/deliverables/${deliverableId}/revision`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ reason }),
    })
    
    if (response.ok && deliverable) {
      queryClient.invalidateQueries({ queryKey: deliverableKeys.detail(deliverableId) })
      loadDeliverable() // Reload to get new comment
    }
  }

  const handleAddComment = async (content: string) => {
    const res = await fetch(`/api/client/deliverables/${deliverableId}/comments`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content }),
    })
    if (res.ok) {
      const json = await res.json()
      if (json.comment) setComments([...comments, json.comment as unknown as Comment])
    }
  }

  async function downloadExport() {
    setDownloading(true)
    try {
      const res = await fetch(`/api/client/deliverables/${deliverableId}/export`)
      if (!res.ok) throw new Error('Gagal mengunduh')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      const cd = res.headers.get('Content-Disposition') ?? ''
      const m = cd.match(/filename="([^"]+)"/)
      a.download = m ? m[1] : `${deliverable?.title ?? 'deliverable'}.md`
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(url)
    } catch {
      // the page stays usable; surface via button state reset below
    } finally {
      setDownloading(false)
    }
  }

  if (!deliverable) {
    return (
      <div className="mx-auto w-full max-w-4xl">
        <p className="text-muted-foreground">Deliverable tidak ditemukan.</p>
        <Link href="/client/deliverables" className="inline-flex items-center gap-2 text-sm text-primary hover:underline mt-4">
          <Icons.arrowLeft className="w-4 h-4" />
          Kembali ke Daftar
        </Link>
      </div>
    )
  }

  const canAction = deliverable.status === 'sent'

  return (
    <div className="mx-auto w-full max-w-4xl">
      <div className="mb-6">
        <Link href="/client/deliverables" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors mb-4">
          <Icons.arrowLeft className="w-4 h-4" />
          Kembali
        </Link>
        
        <div className="flex items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">{deliverable.title}</h1>
            <div className="flex items-center gap-3 mt-2">
              <TypeBadge type={deliverable.type} />
              <StatusBadge status={deliverable.status} />
            </div>
          </div>
          
          <div className="flex items-center gap-2">
