              </div>
              
              <Separator />
              
              <div className="flex items-center gap-3">
                <Icons.clock className="w-4 h-4 text-muted-foreground" />
                <div>
                  <p className="text-muted-foreground">Terakhir diubah</p>
                  <p className="font-medium">
                    {new Date(deliverable.updated_at).toLocaleDateString('id-ID', {
                      day: 'numeric',
                      month: 'long',
                      year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Status</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Icons.circleCheck className="w-4 h-4 text-primary" />
                  <span className="text-sm">Terkirim dari tim</span>
                </div>
                {deliverable.status === 'approved' && (
                  <div className="flex items-center gap-2">
                    <Icons.circleCheck className="w-4 h-4 text-green-600" />
                    <span className="text-sm font-medium text-green-600">Disetujui oleh Anda</span>
