                )}
                {deliverable.status === 'revision_requested' && (
                  <div className="flex items-center gap-2">
                    <Icons.chat className="w-4 h-4 text-orange-600" />
                    <span className="text-sm font-medium text-orange-600">Revisi diminta</span>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useQueryState, parseAsString } from 'nuqs'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card'
import { CompetitorBenchmarkCard } from '@/components/analytics/competitor-benchmark-card'
import { ROIAnalyticalForecastCard } from '@/components/analytics/roi-forecast-card'
import { SentimentOverviewCard } from '@/components/analytics/sentiment-overview-card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import ReactMarkdown from 'react-markdown'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'
import {
  analyticsPostsQueryOptions,
  analyticsSummariesQueryOptions,
  generateInsightMutation,
  updateMetricMutation,
  invalidateAnalytics,
} from '@/features/analytics/api/queries'
import type {
  PostMetric,
  MetricField,
} from '@/features/analytics/api/types'

type InlineEditState = {
  postId: string
  field: MetricField
}

export function AnalyticsBoard({ clientId }: { clientId: string }) {
  const queryClient = useQueryClient()

  const [periodStart] = useQueryState('from', parseAsString.withDefault(''))
  const [periodEnd] = useQueryState('to', parseAsString.withDefault(''))
  const [selCampaign] = useQueryState('campaign', parseAsString.withDefault(''))

  const [generating, setGenerating] = useState(false)
  const [editingCell, setEditingCell] = useState<InlineEditState | null>(null)
  const [editValue, setEditValue] = useState('')

  // Queries
  const { data: posts = [], isLoading: loadingPosts } = useQuery(analyticsPostsQueryOptions(clientId))
  const { data: summaries = [] } = useQuery(analyticsSummariesQueryOptions(clientId))

  // Mutations
  const generateInsight = useMutation(generateInsightMutation)
  const updateMetric = useMutation(updateMetricMutation)

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!periodStart || !periodEnd) return
    setGenerating(true)
    try {
      await generateInsight.mutateAsync({
        clientId,
        periodStart,
        periodEnd,
        campaignTag: selCampaign || undefined,
      })
      invalidateAnalytics(clientId)
      toast.success('Insight berhasil digenerate')
    } catch (err: any) {
      toast.error(err.message || 'Gagal generate insight')
    } finally {
      setGenerating(false)
    }
  }

  const handleUpdateMetric = async (postId: string, field: MetricField, value: number) => {
    try {
      // Optimistic update
      queryClient.setQueryData<PostMetric[]>(
        analyticsPostsQueryOptions(clientId).queryKey,
        (old) =>
          old?.map((p) => {
            if (p.id === postId && Array.isArray(p.post_metrics)) {
              return {
                ...p,
                post_metrics: p.post_metrics.map((m: any) => ({
                  ...m,
                  [field]: value
                }))
              }
            }
            return p
          }) ?? old
      )

      await updateMetric.mutateAsync({ postId, field, value })
    } catch (err: any) {
      toast.error(err.message || 'Gagal update metrik')
      queryClient.invalidateQueries({ queryKey: analyticsPostsQueryOptions(clientId).queryKey })
    }
  }

  const commitEdit = () => {
    if (!editingCell) return
    const value = parseInt(editValue, 10)
    if (isNaN(value) || value < 0) {
      toast.warning('Masukkan angka positif')
      return
    }
    handleUpdateMetric(editingCell.postId, editingCell.field, value)
    setEditingCell(null)
    setEditValue('')
  }

  if (loadingPosts) return <div className="py-20 text-center text-muted-foreground text-sm">Memuat data analitik...</div>

  // Aggregate sentiment totals from posts if available
  let totalProc = 0, posCnt = 0, neuCnt = 0, negCnt = 0, confSum = 0
  posts.forEach(p => {
    if (Array.isArray(p.post_metrics)) {
      p.post_metrics.forEach((m: any) => {
        if (m.sentiment_summary) {
          totalProc += m.sentiment_summary.total_processed || 0
          posCnt += m.sentiment_summary.positive_count || 0
          neuCnt += m.sentiment_summary.neutral_count || 0
          negCnt += m.sentiment_summary.negative_count || 0
          confSum += m.sentiment_summary.avg_confidence || 0
        }
      })
    }
  })

  return (
    <div className="space-y-8">
      {/* Main Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Icons.kanban className="size-5 text-primary" />
            Detail Performa Konten
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b bg-muted/50">
                  <th className="p-3 text-left">Konten</th>
                  <th className="p-3 text-center">Reach</th>
                  <th className="p-3 text-center">Likes</th>
                  <th className="p-3 text-center">Comments</th>
                </tr>
              </thead>
              <tbody>
                {posts.map(post => (
                  <tr key={post.id} className="border-b hover:bg-muted/30 transition-colors">
                    <td className="p-3 font-medium">{post.title}</td>
                    {(['reach', 'likes', 'comments'] as const).map(field => {
                      const metrics = Array.isArray(post.post_metrics) ? post.post_metrics[0] : (post.post_metrics as any)
                      const val = metrics?.[field] ?? 0
                      const isEditing = editingCell?.postId === post.id && editingCell?.field === field

                      return (
                        <td key={field} className="p-3 text-center cursor-pointer hover:bg-primary/5" onClick={() => {
                          setEditingCell({ postId: post.id, field })
                          setEditValue(String(val))
                        }}>
                          {isEditing ? (
                            <Input 
                              autoFocus
                              value={editValue}
                              onChange={e => setEditValue(e.target.value)}
                              onBlur={commitEdit}
                              onKeyDown={e => e.key === 'Enter' && commitEdit()}
                              className="h-8 w-20 mx-auto text-center"
                            />
                          ) : val.toLocaleString()}
                        </td>
                      )
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* AI Insight Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-lg flex items-center gap-2">
              <Icons.sparkles className="size-5 text-amber-500" />
              AI Performance Analysis
            </CardTitle>
            <Button onClick={handleGenerate} disabled={generating} size="sm">
              {generating ? <Icons.spinner className="mr-2 size-4 animate-spin" /> : <Icons.refresh className="mr-2 size-4" />}
              Generate Insight Baru
            </Button>
          </CardHeader>
          <CardContent>
            {summaries.length > 0 ? (
              <div className="prose prose-sm dark:prose-invert max-w-none">
                <ReactMarkdown>{summaries[0].ai_insight}</ReactMarkdown>
              </div>
            ) : (
              <p className="text-center py-10 text-muted-foreground">Belum ada insight. Klik generate untuk memulai.</p>
            )}
          </CardContent>
        </Card>

        <SentimentOverviewCard
          positiveCount={posCnt}
          neutralCount={neuCnt}
          negativeCount={negCnt}
          totalProcessed={totalProc}
          avgConfidence={totalProc > 0 ? confSum / posts.length : 0}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <ROIAnalyticalForecastCard clientId={clientId} />
        <CompetitorBenchmarkCard clientId={clientId} />
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ArrowLeft } from '@/registry/icons/arrow-left'
import { ArrowRight } from '@/registry/icons/arrow-right'
import { DndContext, useSensor, useSensors, PointerSensor, TouchSensor, useDraggable, useDroppable } from '@dnd-kit/core'

import { ScheduledPost, PLATFORMS, ScheduledPostUpdate } from '@/features/calendar/types'
import { PlatformIcon } from '@/components/calendar/platform-icon'
import { PostCard } from '@/components/calendar/post-card'
import { timeStr, getDotColor } from '@/features/calendar/utils'

function DraggablePostItem({ post, children }: { post: ScheduledPost; children: React.ReactNode }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: post.id,
    data: post,
  })

  const style = transform ? {
    transform: `translate3d(${transform.x}px, ${transform.y}px, 0) scale(1.05)`,
    zIndex: 999,
  } : undefined

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...listeners}
      {...attributes}
      className={`relative cursor-grab active:cursor-grabbing transition-shadow ${isDragging ? 'opacity-90 shadow-2xl ring-2 ring-primary/50 rounded-lg' : ''}`}
      onClick={(e) => {
        // Prevent drag events from interfering with click (if any)
        e.stopPropagation()
      }}
    >
      {children}
    </div>
  )
}

function DroppableDayCell({
  day,
  dateIso,
  isSelected,
  isToday,
  onClick,
  children,
}: {
  day: number
  dateIso: string
  isSelected: boolean
  isToday: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  const { isOver, setNodeRef } = useDroppable({
    id: `day-${dateIso}`,
    data: { dateIso },
  })

  return (
    <div
      ref={setNodeRef}
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') onClick()
      }}
      className={`h-20 sm:h-24 p-1.5 sm:p-2 rounded-lg border text-left flex flex-col justify-between transition-all group cursor-pointer ${
        isOver
          ? 'border-green-500 ring-2 ring-green-500/40 bg-green-500/10'
          : isSelected
          ? 'border-primary ring-2 ring-primary/20 bg-primary/5'
          : isToday
          ? 'border-blue-500/50 bg-blue-500/5'
          : 'border-border/60 hover:border-border hover:bg-muted/30 bg-card'
      }`}
    >
      {children}
    </div>
  )
}

export function CalendarView({
  posts,
  role = 'admin',
  onSelectPost,
  onAddPost,
  onUpdatePost,
  viewMode = 'calendar',
  onViewModeChange,
}: {
  posts: ScheduledPost[]
  role?: 'admin' | 'client'
  onSelectPost?: (post: ScheduledPost) => void
  onAddPost?: (date: Date) => void
  onUpdatePost?: (postId: string, data: ScheduledPostUpdate) => Promise<void>
  viewMode?: 'calendar' | 'list'
  onViewModeChange?: (mode: 'calendar' | 'list') => void
}) {
  const [currentDate, setCurrentDate] = useState(() => new Date())
  const [selectedDay, setSelectedDay] = useState<number | null>(() => new Date().getDate())
  const [selectedPlatform, setSelectedPlatform] = useState<string>('all')

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 250, tolerance: 5 },
    })
  )

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event
    
    if (!over) return

    const postId = active.id
    const newDateIso = over.data.current?.dateIso
    
    if (newDateIso) {
      // Find the post and invoke an update callback if we passed one down,
      // or we can handle it via onUpdatePost in props.
      // For now, we will assume there is an onUpdatePost prop or we update local state.
      // Since posts is passed as prop, we'll invoke a callback if provided.
      if (onUpdatePost) {
        const post = posts.find((p) => p.id === postId)
        if (post) {
          // Construct new ISO string keeping the time but changing the date
          const oldDate = new Date(post.scheduled_at)
          const newDate = new Date(newDateIso)
          newDate.setHours(oldDate.getHours(), oldDate.getMinutes(), oldDate.getSeconds())
          
          await onUpdatePost(postId, { scheduled_at: newDate.toISOString() })
        }
      }
    }
  }

  const year = currentDate.getFullYear()
  const month = currentDate.getMonth()

  const firstDayIndex = new Date(year, month, 1).getDay()
  const totalDays = new Date(year, month + 1, 0).getDate()

  const MONTH_NAMES = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
  ]

  const prevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1))
    setSelectedDay(null)
  }

  const nextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1))
    setSelectedDay(null)
  }

  const filteredPosts = posts.filter((p) => {
    const d = new Date(p.scheduled_at)
    const matchesMonth = viewMode === 'list' || (d.getFullYear() === year && d.getMonth() === month)
    const matchesPlatform = selectedPlatform === 'all' || p.platform.toLowerCase() === selectedPlatform
    return matchesMonth && matchesPlatform
  })

  const sortedPosts = [...filteredPosts].sort((a, b) => new Date(a.scheduled_at).getTime() - new Date(b.scheduled_at).getTime())

  const postsByDay: Record<number, ScheduledPost[]> = {}
  for (const post of filteredPosts) {
    const day = new Date(post.scheduled_at).getDate()
    if (!postsByDay[day]) postsByDay[day] = []
    postsByDay[day].push(post)
  }

  const selectedDayPosts = selectedDay ? (postsByDay[selectedDay] ?? []) : []

  return (
    <div className="space-y-6">
      {/* Header controls + View Toggle */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <Button variant="outline" size="icon" onClick={prevMonth} className="h-11 w-11 lg:h-9 lg:w-9" disabled={viewMode === 'list'} aria-label="Bulan sebelumnya">
            <ArrowLeft className="size-4" />
          </Button>
          <h2 className="text-xl font-bold tracking-tight min-w-44 text-center">
            {MONTH_NAMES[month]} {year}
          </h2>
          <Button variant="outline" size="icon" onClick={nextMonth} className="h-11 w-11 lg:h-9 lg:w-9" disabled={viewMode === 'list'} aria-label="Bulan berikutnya">
            <ArrowRight className="size-4" />
          </Button>
        </div>

        {/* Mobile: List/Calendar tab switch */}
        <div className="flex items-center gap-1 bg-muted/60 p-1 rounded-xl" role="tablist" aria-label="Tampilan kalender">
          <button
            type="button"
            role="tab"
            aria-selected={viewMode === 'calendar'}
            onClick={() => onViewModeChange?.('calendar')}
            className={`min-h-[44px] sm:min-h-0 px-3 py-2 sm:py-1.5 rounded-lg text-xs font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${viewMode === 'calendar' ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
          >
            Kalender
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={viewMode === 'list'}
            onClick={() => onViewModeChange?.('list')}
            className={`min-h-[44px] sm:min-h-0 px-3 py-2 sm:py-1.5 rounded-lg text-xs font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${viewMode === 'list' ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
          >
            Daftar
          </button>
        </div>

        {/* Platform filter pills (calendar only) */}
        {viewMode === 'calendar' && (
          <div className="flex flex-wrap items-center gap-1.5 bg-muted/60 p-1 rounded-xl" role="group" aria-label="Filter platform">
            <button
              type="button"
              onClick={() => setSelectedPlatform('all')}
              className={`min-h-[44px] sm:min-h-0 px-3 py-2 sm:py-1.5 rounded-lg text-xs font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${selectedPlatform === 'all' ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
            >
              Semua Platform
            </button>
            {Object.entries(PLATFORMS).map(([id, info]) => (
              <button
                key={id}
                type="button"
                onClick={() => setSelectedPlatform(id)}
                className={`min-h-[44px] sm:min-h-0 flex items-center gap-1.5 px-3 py-2 sm:py-1.5 rounded-lg text-xs font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${selectedPlatform === id ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
              >
                <PlatformIcon platform={id} className="size-3.5" />
                <span>{info.name}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Conditional render: Calendar Grid vs List */}
      {viewMode === 'calendar' ? (
        <DndContext id="frhm-calendar-dnd" sensors={sensors} onDragEnd={handleDragEnd}>
          <Card>
          <CardContent className="p-4 sm:p-6">
            <div className="overflow-x-auto -mx-4 px-4 sm:mx-0 sm:px-0">
            <div className="min-w-[560px]">
            {/* Day headers (Min - Sab) */}
            <div className="grid grid-cols-7 gap-1 text-center mb-2">
              {['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'].map((d, idx) => (
                <div
                  key={d}
                  className={`text-xs font-semibold py-2 ${idx === 0 || idx === 6 ? 'text-muted-foreground' : 'text-foreground'}`}
                >
                  {d}
                </div>
              ))}
            </div>

            {/* Day cells */}
            <div className="grid grid-cols-7 gap-1.5">
              {Array.from({ length: firstDayIndex }).map((_, idx) => (
                <div key={`empty-${idx}`} className="h-20 sm:h-24 rounded-lg bg-muted/20 border border-transparent opacity-40" />
              ))}
              {Array.from({ length: totalDays }).map((_, idx) => {
                const day = idx + 1
                const dayPosts = postsByDay[day] ?? []
                const isSelected = selectedDay === day
                const isToday =
                  day === new Date().getDate() &&
                  month === new Date().getMonth() &&
                  year === new Date().getFullYear()

                const dateIso = new Date(year, month, day).toISOString()

                return (
                  <DroppableDayCell
                    key={day}
                    day={day}
                    dateIso={dateIso}
                    isSelected={isSelected}
                    isToday={isToday}
                    onClick={() => setSelectedDay(day)}
                  >
                    <div className="flex items-center justify-between w-full">
                      <span
                        className={`text-xs font-semibold rounded-full size-6 flex items-center justify-center ${isToday ? 'bg-primary text-primary-foreground' : isSelected ? 'bg-muted text-foreground' : 'text-muted-foreground group-hover:text-foreground'}`}
                      >
                        {day}
                      </span>
                      {dayPosts.length > 0 && (
                        <span className="text-[10px] font-bold text-muted-foreground">
                          {dayPosts.length}
                        </span>
                      )}
                    </div>
                    {/* Post badges summary in cell, dot colored per platform+status */}
                    <div className="space-y-1 overflow-hidden w-full">
                      {dayPosts.slice(0, 2).map((p) => (
                        <DraggablePostItem key={p.id} post={p}>
                          <div
                            className={`flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] truncate border ${
                              p.is_placeholder
                                ? 'bg-purple-500/10 border-purple-500/30 text-purple-700 dark:text-purple-400'
                                : PLATFORMS[p.platform]?.bg ?? 'bg-muted'
                            }`}
                          >
                            <span className={`size-1.5 rounded-full shrink-0 ${getDotColor(p)}`} />
                            {p.is_placeholder ? (
                              <span className="truncate flex-1">
                                {p.reserved_for ?? 'Slot kosong'}
                              </span>
                            ) : p.title.length > 12 ? (
                              `${p.title.slice(0, 12)}…`
                            ) : (
                              p.title
                            )}
                          </div>
                        </DraggablePostItem>
                      ))}
                      {dayPosts.length > 2 && (
                        <p className="text-[9px] text-muted-foreground font-medium text-center">
                          +{dayPosts.length - 2} lagi
                        </p>
                      )}
                    </div>
                  </DroppableDayCell>
                )
              })}
            </div>
            </div>
            </div>
          </CardContent>
        </Card>
        </DndContext>
      ) : (
        // List View
        <Card>
          <CardHeader>
            <CardTitle>Semua Postingan Terjadwal</CardTitle>
            <CardDescription>{sortedPosts.length} postingan ditemukan untuk bulan ini</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {sortedPosts.length === 0 ? (
                <p className="py-8 text-center text-sm text-muted-foreground">
                  Tidak ada postingan yang cocok dengan filter.
                </p>
              ) : (
                sortedPosts.map((post) => (
                  <PostCard
                    key={post.id}
                    post={post}
                    layout="list"
                    showTimeSuffix
                    onClick={() => onSelectPost?.(post)}
                  />
                ))
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Selected Day Panel */}
      {viewMode === 'calendar' && (
        <Card className="flex flex-col">
          <CardHeader className="pb-3 border-b">
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-base">
                  {selectedDay ? `${selectedDay} ${MONTH_NAMES[month]} ${year}` : 'Pilih Tanggal'}
                </CardTitle>
                <CardDescription>
                  {selectedDayPosts.length} postingan terjadwal
                </CardDescription>
              </div>
              {role === 'admin' && selectedDay && onAddPost && (
                <Button size="sm" onClick={() => onAddPost(new Date(year, month, selectedDay))} className="h-9 px-3 text-xs">
                  + Tambah
                </Button>
              )}
            </div>
          </CardHeader>
          <CardContent className="flex-1 p-4 space-y-3 overflow-auto max-h-[32rem]">
            {!selectedDay ? (
              <p className="py-8 text-center text-sm text-muted-foreground">
                Klik tanggal di kalender untuk melihat daftar postingan.
              </p>
            ) : selectedDayPosts.length === 0 ? (
              <div className="py-8 text-center space-y-2">
                <p className="text-sm text-muted-foreground">
                  Tidak ada postingan di tanggal ini.
                </p>
                {role === 'admin' && onAddPost && (
                  <Button variant="outline" size="sm" onClick={() => onAddPost(new Date(year, month, selectedDay))} className="h-9">
                    + Jadwalkan Postingan
                  </Button>
                )}
              </div>
            ) : (
              selectedDayPosts.map((post) => (
                <PostCard
                  key={post.id}
                  post={post}
                  layout="compact"
                  showTimeSuffix
                  onClick={() => onSelectPost?.(post)}
                />
              ))
            )}
          </CardContent>
        </Card>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Icons } from '@/components/icons'

export function BrandAssetHub({ clientId }: { clientId: string }) {
  const [assets, setAssets] = useState<{ id: string; file_path: string; category: string }[]>([])
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [guidelines, setGuidelines] = useState('')
  const [savingGuide, setSavingGuide] = useState(false)
  const supabase = createClient()

  useEffect(() => {
    fetchAssets()
  }, [clientId])

  const fetchAssets = async () => {
    setLoading(true)
    const { data } = await supabase
      .from('brand_assets')
      .select('*')
      .eq('client_id', clientId)
      .order('created_at', { ascending: false })
    
    if (data) {
      setAssets(data)
      const guideAsset = data.find(a => a.category === 'guidelines')
      if (guideAsset && guideAsset.guidelines) {
        setGuidelines(guideAsset.guidelines)
      }
    }
    setLoading(false)
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)
    const fileExt = file.name.split('.').pop()
    // crypto.randomUUID() instead of Math.random(): collision-safe, crypto-grade entropy
    const fileName = `${clientId}/${crypto.randomUUID()}.${fileExt}`
    
    const { error: uploadError } = await supabase.storage
      .from('brand_assets')
      .upload(fileName, file)

    if (!uploadError) {
      const res = await fetch('/api/client/assets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          category: 'file',
          file_path: fileName,
          file_type: file.type,
        })
      })
      if (res.ok) {
        fetchAssets()
      }
    }
    setUploading(false)
  }

  const handleSaveGuidelines = async () => {
    setSavingGuide(true)
    await fetch('/api/client/assets', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        client_id: clientId,
        category: 'guidelines',
        guidelines
      })
    })
    fetchAssets()
    setSavingGuide(false)
  }

  const handleDelete = async (id: string) => {
    await fetch(`/api/client/assets?id=${id}`, { method: 'DELETE' })
    fetchAssets()
  }

  const getFileUrl = async (path: string): Promise<string | null> => {
    // Bucket is private — createSignedUrl is required, getPublicUrl returns a 404.
    const { data, error } = await supabase.storage.from('brand_assets').createSignedUrl(path, 3600)
    if (error) return null
    return data.signedUrl
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      <Card>
        <CardHeader>
          <CardTitle>Brand Assets</CardTitle>
          <CardDescription>Upload logos, fonts, and other assets</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-4">
            <Input type="file" onChange={handleFileUpload} disabled={uploading} className="w-full" />
            {uploading && <Icons.spinner className="animate-spin size-4 text-muted-foreground" />}
          </div>
          
          <div className="space-y-2 mt-4">
            {loading ? (
              <div className="flex justify-center p-4"><Icons.spinner className="animate-spin size-4" /></div>
            ) : (
              assets.filter(a => a.category !== 'guidelines').map((asset) => (
                <div key={asset.id} className="flex items-center justify-between p-3 border rounded-lg">
                  <div className="flex items-center gap-3 overflow-hidden">
                    <Icons.page className="size-4 shrink-0 text-muted-foreground" />
                    <span className="text-sm truncate">{asset.file_path.split('/').pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" onClick={async () => {
                      const url = await getFileUrl(asset.file_path)
                      if (url) window.open(url, '_blank')
                    }}>
                      <Icons.download className="size-4" />
                    </Button>
                    <Button variant="ghost" size="icon" onClick={() => handleDelete(asset.id)}>
                      <Icons.trash className="size-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))
            )}
            {assets.filter(a => a.category !== 'guidelines').length === 0 && !loading && (
              <p className="text-sm text-muted-foreground text-center py-4">Belum ada aset.</p>
            )}
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Brand Guidelines</CardTitle>
          <CardDescription>Catat warna HEX, tipografi, atau aturan brand</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Catatan Guidelines</Label>
            <Textarea 
              placeholder="Contoh: Primary Color: #FF0000, Font: Inter..." 
              value={guidelines}
              onChange={(e) => setGuidelines(e.target.value)}
              className="min-h-[150px]"
            />
          </div>
          <Button onClick={handleSaveGuidelines} disabled={savingGuide}>
            {savingGuide ? <Icons.spinner className="animate-spin mr-2 size-4" /> : null}
            Simpan Guidelines
          </Button>
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as z from 'zod'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'

const formSchema = z.object({
  campaign_name: z.string().min(2, 'Nama kampanye minimal 2 karakter'),
  spend: z.coerce.number().min(0, 'Angka positif'),
  clicks: z.coerce.number().min(0, 'Angka positif'),
  log_date: z.string().min(1, 'Tanggal wajib diisi')
})

type FormData = z.infer<typeof formSchema>

interface AdSpendFormModalProps {
  clientId: string
  children: React.ReactNode
  onSuccess?: (log: any) => void
}

export function AdSpendFormModal({ clientId, children, onSuccess }: AdSpendFormModalProps) {
  const [open, setOpen] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  
  const { register, handleSubmit, formState: { errors }, reset } = useForm<FormData>({
    resolver: zodResolver(formSchema as any),
    defaultValues: {
      campaign_name: '',
      spend: 0,
      clicks: 0,
      log_date: new Date().toISOString().split('T')[0]
    }
  })

  const onSubmit = async (data: FormData) => {
    setIsSubmitting(true)
    
    try {
      const res = await fetch(`/api/admin/clients/${clientId}/ad-spend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal mencatat data iklan')
      
      reset()
      setOpen(false)
      if (onSuccess && json.ad_spend_log) {
        onSuccess(json.ad_spend_log)
      }
    } catch (err) {
      console.error('Error recording ad spend:', err)
      toast.error('Gagal mencatat data iklan. Silakan coba lagi.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger>
        {children}
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Log Ad Spend</DialogTitle>
          <DialogDescription>
            Catat pengeluaran dan klik iklan harian.
          </DialogDescription>
        </DialogHeader>
        
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="campaign_name">Nama Campaign <span className="text-destructive">*</span></Label>
            <Input id="campaign_name" placeholder="Misal: Promo Q3" {...register('campaign_name')} />
            {errors.campaign_name && <p className="text-xs text-destructive">{errors.campaign_name.message}</p>}
          </div>
          
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="spend">Spend (IDR) <span className="text-destructive">*</span></Label>
              <Input id="spend" type="number" min="0" placeholder="Misal: 50000" {...register('spend')} />
              {errors.spend && <p className="text-xs text-destructive">{errors.spend.message}</p>}
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="clicks">Clicks <span className="text-destructive">*</span></Label>
              <Input id="clicks" type="number" min="0" placeholder="Misal: 120" {...register('clicks')} />
              {errors.clicks && <p className="text-xs text-destructive">{errors.clicks.message}</p>}
            </div>
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="log_date">Tanggal <span className="text-destructive">*</span></Label>
            <Input id="log_date" type="date" {...register('log_date')} />
            {errors.log_date && <p className="text-xs text-destructive">{errors.log_date.message}</p>}
          </div>
          
          <DialogFooter className="pt-4">
            <Button type="button" variant="outline" onClick={() => setOpen(false)} disabled={isSubmitting}>
              Batal
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? (
                <>
                  <Icons.spinner className="mr-2 h-4 w-4 animate-spin" />
                  Menyimpan...
                </>
              ) : (
                'Simpan Log'
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as z from 'zod'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'

const formSchema = z.object({
  month: z.string().min(1, 'Pilih bulan'),
  total_budget: z.coerce.number().min(1, 'Budget harus lebih dari 0'),
})

type FormData = z.infer<typeof formSchema>

interface BudgetFormModalProps {
  clientId: string
  children: React.ReactNode
  onSuccess?: (budget: any) => void
}

export function BudgetFormModal({ clientId, children, onSuccess }: BudgetFormModalProps) {
  const [open, setOpen] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  
  const { register, handleSubmit, formState: { errors }, reset } = useForm<FormData>({
    resolver: zodResolver(formSchema as any),
    defaultValues: {
      month: '',
      total_budget: 0
    }
  })

  const onSubmit = async (data: FormData) => {
    setIsSubmitting(true)

    try {
      const res = await fetch(`/api/admin/clients/${clientId}/budgets`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ month: data.month, total_budget: data.total_budget }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal menyimpan budget')

      reset()
      setOpen(false)
      if (onSuccess && json.budget) {
        onSuccess(json.budget)
      }
    } catch (err) {
      console.error('Error setting budget:', err)
      toast.error('Gagal menyimpan budget. Silakan coba lagi.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger>
        {children}
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Set Monthly Budget</DialogTitle>
          <DialogDescription>
