type FormData = z.infer<typeof formSchema>

interface ExpenseFormModalProps {
  clientId: string
  budgetId: string | undefined
  children: React.ReactNode
  onSuccess?: (expense: { id: string; amount: number; category: string; description: string; expense_date: string }) => void
}

export function ExpenseFormModal({ clientId, budgetId, children, onSuccess }: ExpenseFormModalProps) {
  const [open, setOpen] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [kols, setKols] = useState<{ id: string; name: string; rate_card: number | null }[]>([])
  const supabase = createClient()
  
  const { register, handleSubmit, formState: { errors }, reset, setValue, watch } = useForm<FormData>({
    resolver: zodResolver(formSchema as any),
    defaultValues: {
      amount: 0,
      category: '',
      description: '',
      expense_date: new Date().toISOString().split('T')[0]
    }
  })

  const selectedCategory = watch('category')

  useEffect(() => {
    if (open) {
      const fetchKols = async () => {
        const { data } = await supabase.from('kols').select('id, name, rate_card').order('name', { ascending: true })
        if (data) setKols(data)
      }
      fetchKols()
    }
  }, [open, supabase])

  const handleKolSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const kolId = e.target.value
    if (!kolId) return
    const kol = kols.find(k => k.id === kolId)
    if (kol) {
      setValue('amount', kol.rate_card || 0, { shouldValidate: true })
      setValue('description', `Pembayaran KOL ${kol.name}`, { shouldValidate: true })
    }
  }

  const onSubmit = async (data: FormData) => {
    setIsSubmitting(true)
    
    try {
      const res = await fetch(`/api/admin/clients/${clientId}/expenses`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          budget_id: budgetId,
          amount: data.amount,
          category: data.category,
          description: data.description,
          expense_date: data.expense_date,
        }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal mencatat pengeluaran')
      
      reset()
      setOpen(false)
      if (onSuccess && json.expense) {
        onSuccess(json.expense)
      }
    } catch (err) {
      console.error('Error recording expense:', err)
      toast.error('Gagal mencatat pengeluaran. Silakan coba lagi.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger>
        {children}
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Catat Pengeluaran Baru</DialogTitle>
          <DialogDescription>
            Masukkan nominal pengeluaran yang akan memotong budget bulanan.
          </DialogDescription>
        </DialogHeader>
        
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="category">Kategori <span className="text-destructive">*</span></Label>
            <select 
              id="category"
              className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
              {...register('category')}
            >
              <option value="" disabled>Pilih Kategori</option>
              <option value="ads">Ads / Iklan</option>
              <option value="kol">KOL / Influencer</option>
              <option value="event">Event / Acara</option>
              <option value="other">Lain-lain</option>
            </select>
            {errors.category && <p className="text-xs text-destructive">{errors.category.message}</p>}
          </div>

          {selectedCategory === 'kol' && (
            <div className="space-y-2 p-3 bg-muted/50 rounded-lg border border-border/50">
              <Label htmlFor="kol_select">Pilih KOL (Auto-fill)</Label>
              <select 
                id="kol_select"
                className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                onChange={handleKolSelect}
                defaultValue=""
              >
                <option value="" disabled>-- Pilih KOL dari CRM --</option>
                {kols.map(kol => (
                  <option key={kol.id} value={kol.id}>{kol.name} (Rp {kol.rate_card?.toLocaleString('id-ID')})</option>
                ))}
              </select>
              <p className="text-xs text-muted-foreground mt-1">Memilih KOL akan otomatis mengisi nominal dan keterangan.</p>
            </div>
          )}
          
          <div className="space-y-2">
            <Label htmlFor="amount">Nominal (IDR) <span className="text-destructive">*</span></Label>
            <Input id="amount" type="number" min="0" placeholder="Misal: 500000" {...register('amount')} />
            {errors.amount && <p className="text-xs text-destructive">{errors.amount.message}</p>}
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="expense_date">Tanggal <span className="text-destructive">*</span></Label>
            <Input id="expense_date" type="date" {...register('expense_date')} />
            {errors.expense_date && <p className="text-xs text-destructive">{errors.expense_date.message}</p>}
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="description">Keterangan <span className="text-destructive">*</span></Label>
            <Input id="description" placeholder="Misal: Pembayaran KOL @username" {...register('description')} />
            {errors.description && <p className="text-xs text-destructive">{errors.description.message}</p>}
          </div>
          
          <DialogFooter className="pt-4">
            <Button type="button" variant="outline" onClick={() => setOpen(false)} disabled={isSubmitting}>
              Batal
            </Button>
            <Button type="submit" disabled={isSubmitting || !budgetId}>
              {isSubmitting ? (
                <>
                  <Icons.spinner className="mr-2 h-4 w-4 animate-spin" />
                  Menyimpan...
                </>
              ) : (
                !budgetId ? 'Atur Budget Dulu' : 'Simpan Pengeluaran'
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useQueryState, parseAsString } from 'nuqs'
import { createClient } from '@/lib/supabase/client'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { KolFormModal, KOL } from './kol-form-modal'
import { toast } from 'sonner'
import Link from 'next/link'

export function KolCrmBoard() {
  const [kols, setKols] = useState<KOL[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useQueryState(
    'q',
    parseAsString.withDefault('').withOptions({ shallow: true })
  )
  const [clientId, setClientId] = useQueryState(
    'client',
    parseAsString.withDefault('').withOptions({ shallow: true })
  )
  const [clients, setClients] = useState<{ id: string; name: string }[]>([])

  const [modalOpen, setModalOpen] = useState(false)
  const [editingKol, setEditingKol] = useState<KOL | null>(null)

  const supabase = createClient()

  // Load client list once (the CRM is global, but kols.client_id is NOT NULL).
  useEffect(() => {
    async function loadClients() {
      const { data } = await supabase
        .from('clients')
        .select('id, name')
        .order('name', { ascending: true })
      if (data) setClients(data)
    }
    loadClients()
  }, [supabase])

  const fetchKols = async () => {
    if (!clientId) return
    setLoading(true)
    const res = await fetch(`/api/admin/kols?client_id=${clientId}`)
    if (res.ok) {
      const data = await res.json()
      setKols(data.kols ?? [])
    }
    setLoading(false)
  }

  useEffect(() => {
    fetchKols()
  }, [clientId])

  const handleOpenNew = () => {
    setEditingKol(null)
    setModalOpen(true)
  }

  const handleOpenEdit = (kol: KOL) => {
    setEditingKol(kol)
    setModalOpen(true)
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Hapus KOL ini dari CRM?')) return
    const res = await fetch('/api/admin/kols', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'delete', id }),
    })
    if (res.ok) {
      setKols(kols.filter((k) => k.id !== id))
    } else {
      const err = await res.json()
      toast.error(err.error || 'Gagal menghapus KOL.')
    }
  }

  const filteredKols = kols.filter((k) => {
    const q = search.toLowerCase()
    return (
      k.name.toLowerCase().includes(q) ||
      (k.niche?.toLowerCase().includes(q) ?? false) ||
      (k.platforms?.some((p) => p.toLowerCase().includes(q)) ?? false)
    )
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-semibold tracking-tight">KOL & Vendor CRM</h3>
          <p className="text-xs text-muted-foreground">
            Kelola database influencer, talent, dan vendor untuk keperluan kampanye.
          </p>
        </div>
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <div className="w-full sm:w-48">
            <Label htmlFor="client-filter" className="sr-only">Klien</Label>
            <select
              id="client-filter"
              className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
              value={clientId}
              onChange={(e) => setClientId(e.target.value)}
            >
              <option value="">Pilih Klien...</option>
              {clients.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div className="relative w-full sm:w-64">
            <Icons.search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              type="search"
              placeholder="Cari nama atau niche..."
              className="pl-8 h-9"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <Button size="sm" onClick={handleOpenNew} disabled={!clientId} className="h-9 whitespace-nowrap">
            <Icons.add className="size-4 mr-2" /> Tambah KOL
          </Button>
        </div>
      </div>

      {!clientId ? (
        <Card>
          <CardContent className="p-8 text-center text-sm text-muted-foreground">
            Pilih klien untuk melihat dan mengelola KOL.
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardContent className="p-0">
            {loading ? (
              <div className="p-8 text-center text-sm text-muted-foreground">Memuat data KOL...</div>
            ) : filteredKols.length === 0 ? (
              <div className="p-8 text-center text-sm text-muted-foreground">
                {search ? 'Tidak ada KOL yang cocok dengan pencarian.' : 'Belum ada data KOL. Silakan tambah baru.'}
              </div>
            ) : (
              <div className="relative w-full overflow-auto">
                <table className="w-full caption-bottom text-sm">
                  <thead className="[&_tr]:border-b">
                    <tr className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                      <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Nama / Username</th>
                      <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Niche</th>
                      <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Platform</th>
                      <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Kontak</th>
                      <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground">Rate Card</th>
                      <th className="h-12 px-4 text-right align-middle font-medium text-muted-foreground">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="[&_tr:last-child]:border-0">
                    {filteredKols.map((kol) => (
                      <tr key={kol.id} className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                        <td className="p-4 align-middle font-medium">
                          <Link href={`/admin/crm/${kol.id}`} className="hover:text-primary hover:underline">
                            {kol.name}
                          </Link>
                        </td>
                        <td className="p-4 align-middle">{kol.niche || '-'}</td>
                        <td className="p-4 align-middle">
                          {kol.platforms && kol.platforms.length > 0 ? (
                            <div className="flex flex-wrap gap-1">
                              {kol.platforms.map((p) => (
                                <span
                                  key={p}
                                  className="inline-flex items-center rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium capitalize text-muted-foreground"
                                >
                                  {p}
                                </span>
                              ))}
                            </div>
                          ) : (
                            '-'
                          )}
                        </td>
                        <td className="p-4 align-middle">{kol.contact_info || '-'}</td>
                        <td className="p-4 align-middle">
                          {kol.rate_card ? `IDR ${kol.rate_card.toLocaleString('id-ID')}` : '-'}
                        </td>
                        <td className="p-4 align-middle text-right">
                          <Button variant="ghost" size="icon" onClick={() => handleOpenEdit(kol)} className="h-8 w-8 text-muted-foreground hover:text-primary">
                            <Icons.edit className="h-4 w-4" />
                            <span className="sr-only">Edit</span>
                          </Button>
                          <Button variant="ghost" size="icon" onClick={() => handleDelete(kol.id)} className="h-8 w-8 text-muted-foreground hover:text-destructive">
                            <Icons.trash className="h-4 w-4" />
                            <span className="sr-only">Hapus</span>
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      <KolFormModal
        open={modalOpen}
        onOpenChange={setModalOpen}
        editingKol={editingKol}
        clientId={clientId}
        onSuccess={fetchKols}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as z from 'zod'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'

const formSchema = z.object({
  name: z.string().min(2, 'Nama KOL minimal 2 karakter'),
  niche: z.string().optional(),
  contact_info: z.string().optional(),
  rate_card: z.coerce.number().min(0, 'Rate card tidak boleh negatif'),
  platforms: z.string().optional(), // comma-separated, converted to text[] on submit
  notes: z.string().optional(),
})

type FormData = z.infer<typeof formSchema>

export type KOL = {
  id: string
  name: string
  niche: string | null
  contact_info: string | null
  rate_card: number | null
  platforms?: string[] | null
  notes?: string | null
}

/** "instagram, tiktok" -> ['instagram','tiktok'] (trimmed, de-duped, lowercased). */
function parsePlatforms(raw?: string): string[] {
  if (!raw) return []
  return Array.from(
    new Set(
      raw
        .split(',')
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean)
    )
  )
}

interface KolFormModalProps {
  children?: React.ReactNode
  open?: boolean
  onOpenChange?: (open: boolean) => void
  editingKol?: KOL | null
  clientId?: string
  onSuccess?: (kol: KOL) => void
}

export function KolFormModal({ children, open: controlledOpen, onOpenChange: controlledOnOpenChange, editingKol, clientId, onSuccess }: KolFormModalProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false)
  const isControlled = controlledOpen !== undefined
  const open = isControlled ? controlledOpen : uncontrolledOpen
  const setOpen = isControlled ? controlledOnOpenChange! : setUncontrolledOpen

  const [isSubmitting, setIsSubmitting] = useState(false)
  
  const { register, handleSubmit, formState: { errors }, reset } = useForm<FormData>({
    resolver: zodResolver(formSchema as any),
    defaultValues: {
      name: '',
      niche: '',
      contact_info: '',
      rate_card: 0,
      platforms: '',
      notes: '',
    }
  })

  useEffect(() => {
    if (open) {
      if (editingKol) {
        reset({
          name: editingKol.name,
          niche: editingKol.niche || '',
          contact_info: editingKol.contact_info || '',
          rate_card: editingKol.rate_card || 0,
          platforms: (editingKol.platforms || []).join(', '),
          notes: editingKol.notes || '',
        })
      } else {
        reset({
          name: '',
          niche: '',
          contact_info: '',
          rate_card: 0,
          platforms: '',
          notes: '',
        })
      }
    }
  }, [open, editingKol, reset])

  const onSubmit = async (data: FormData) => {
    setIsSubmitting(true)
    
    try {
      const res = await fetch('/api/admin/kols', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: editingKol ? 'update' : 'create',
          client_id: clientId,
          id: editingKol?.id,
          name: data.name,
          niche: data.niche || null,
          contact_info: data.contact_info || null,
          rate_card: data.rate_card || 0,
          platforms: parsePlatforms(data.platforms),
          notes: data.notes || null,
        }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal menyimpan data KOL')
      
      reset()
      setOpen(false)
      if (onSuccess && json.kol) {
        onSuccess(json.kol as KOL)
      } else if (!editingKol) {
        onSuccess?.({ id: '', name: data.name, niche: data.niche || null, contact_info: data.contact_info || null, rate_card: data.rate_card || 0, platforms: parsePlatforms(data.platforms), notes: data.notes || null } as KOL)
      }
    } catch (err) {
      console.error('Error saving KOL:', err)
      toast.error('Gagal menyimpan data KOL. Silakan coba lagi.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      {children && (
        <DialogTrigger>
          {children}
        </DialogTrigger>
      )}
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>{editingKol ? 'Edit Data KOL' : 'Tambah KOL Baru'}</DialogTitle>
          <DialogDescription>
            Masukkan informasi detail influencer/KOL ke dalam database CRM.
          </DialogDescription>
        </DialogHeader>
        
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="name">Nama KOL / Username <span className="text-destructive">*</span></Label>
            <Input id="name" placeholder="Misal: @budi_traveler" {...register('name')} />
            {errors.name && <p className="text-xs text-destructive">{errors.name.message}</p>}
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="niche">Niche / Spesialisasi</Label>
            <Input id="niche" placeholder="Misal: Travel, Food, Tech" {...register('niche')} />
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="contact_info">Kontak (Email / WA / Line)</Label>
            <Input id="contact_info" placeholder="Misal: 08123456789 atau budi@email.com" {...register('contact_info')} />
          </div>
          
          <div className="space-y-2">
            <Label htmlFor="platforms">Platform</Label>
            <Input
              id="platforms"
              placeholder="Misal: instagram, tiktok, youtube"
              {...register('platforms')}
            />
            <p className="text-[11px] text-muted-foreground">Pisahkan dengan koma.</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="rate_card">Rate Card (IDR)</Label>
            <Input id="rate_card" type="number" min="0" placeholder="Misal: 5000000" {...register('rate_card')} />
            {errors.rate_card && <p className="text-xs text-destructive">{errors.rate_card.message}</p>}
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Catatan</Label>
            <Textarea
              id="notes"
              placeholder="Catatan tambahan: preferensi konten, histori kerja sama, dsb."
              rows={3}
              {...register('notes')}
            />
          </div>
          
          <DialogFooter className="pt-4">
            <Button type="button" variant="outline" onClick={() => setOpen(false)} disabled={isSubmitting}>
              Batal
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? (
                <>
                  <Icons.spinner className="mr-2 h-4 w-4 animate-spin" />
                  Menyimpan...
                </>
              ) : (
                'Simpan'
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Icons } from '@/components/icons'
import { toast } from 'sonner'
import { useEffect, useState } from 'react'

export function ClientReminderSettings({ clientId, embedded = false }: { clientId: string; embedded?: boolean }) {
  const supabase = createClient()
  const [enabled, setEnabled] = useState(false)
  const [hour, setHour] = useState(9)
  const [channel, setChannel] = useState<'telegram' | 'email' | 'both'>('telegram')
  const [saving, setSaving] = useState(false)

  // Fetch existing settings
  const { data, isLoading } = useQuery({
    queryKey: ['reminder-settings', clientId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('reminder_settings')
        .select('*')
        .eq('client_id', clientId)
        .maybeSingle()
      if (error) throw error
      return data ?? null
    },
  })

  // Initialize state from fetched data
  useEffect(() => {
    if (data) {
      setEnabled(data.enabled)
      setHour(data.reminder_hour ?? 9)
      setChannel((data.reminder_channel as 'telegram' | 'email' | 'both') || 'telegram')
    }
  }, [data])

  const handleSave = async () => {
    setSaving(true)
    try {
      const { error } = await supabase
        .from('reminder_settings')
        .upsert({
          client_id: clientId,
          enabled,
          reminder_hour: hour,
          reminder_channel: channel,
        })
      if (error) throw error
      toast.success('Pengaturan pengingat tersimpan')
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Gagal menyimpan')
    } finally {
      setSaving(false)
    }
  }

  const content = (
    <div className={embedded ? 'space-y-4' : undefined}>
      {/* Toggle */}
      <div className="flex items-center justify-between">
        <div>
          <Label htmlFor="reminder-enable" className="font-medium">Aktifkan pengingat</Label>
          <p className="text-xs text-muted-foreground">
            Kirim notifikasi H-1 sebelum jadwal tayang.
          </p>
        </div>
        <Button
          id="reminder-enable"
          variant={enabled ? 'default' : 'outline'}
          onClick={() => setEnabled(!enabled)}
          type="button"
        >
          {enabled ? 'Aktif' : 'Nonaktif'}
        </Button>
      </div>

        {/* Time selection */}
        <div className="flex items-end gap-3">
          <div className="flex-1">
            <Label htmlFor="reminder-hour" className="mb-1 block">Waktu pengingat (WIB)</Label>
            <Input
              id="reminder-hour"
              type="number"
              min={0}
              max={23}
              value={hour}
              onChange={(e) => setHour(Number(e.target.value))}
              disabled={!enabled}
              className="w-24"
            />
          </div>
          <div className="text-xs text-muted-foreground py-3">
            Pengingat akan dikirim setiap hari pada pukul {hour}:00 WIB.
          </div>
        </div>

        {/* Channel */}
        {enabled && (
          <div>
            <Label className="mb-1 block">Saluran</Label>
            <div className="flex items-center gap-2">
              {['telegram', 'email', 'both'].map((c) => (
                <Button
                  key={c}
                  type="button"
                  variant={channel === c ? 'default' : 'outline'}
                  onClick={() => setChannel(c as typeof channel)}
                  size="sm"
                  disabled={!enabled}
                >
                  {c === 'telegram' ? 'Telegram' : c === 'email' ? 'Email' : 'Keduanya'}
                </Button>
              ))}
            </div>
          </div>
        )}

        {/* Last sent info */}
        {data?.last_sent_at && (
          <div className="text-xs text-muted-foreground">
            Pengingat terakhir dikirim:{' '}
            {new Date(data.last_sent_at).toLocaleString('id-ID')}
          </div>
        )}

        <div className="flex justify-end">
          <Button onClick={handleSave} disabled={!enabled || saving}>
            {saving ? 'Menyimpan...' : 'Simpan'}
          </Button>
        </div>
    </div>
  )

  if (embedded) return content

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base flex items-center gap-2">
          <Icons.bell className="size-4" />
          Pengingat Jadwal
        </CardTitle>
        <CardDescription>
          Atur jadwal notifikasi pengingat untuk postingan yang akan tayang.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {content}
      </CardContent>
    </Card>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'

import { PostDialog } from '@/components/calendar/post-dialog'
import { ContentFormModal } from './content-form-modal'
import { toast } from 'sonner'
import { Icons } from '@/components/icons'
import { Skeleton } from '@/components/ui/skeleton'
import { PlatformIcon } from '@/components/calendar/platform-icon'
import type { RealtimeChannel } from '@/lib/supabase/client'
import { getTaskSkillStages } from '@/lib/ai/task-context'
import {
  productionsQueryOptions,
  productionKeys,
  deleteProductionMutation,
} from '@/features/production/api/queries'

export type ProductionItem = {
  id: string
  client_id: string
  title: string
  platform: string
  stage: 'idea' | 'script' | 'shooting' | 'editing' | 'design' | 'caption' | 'review' | 'ready'
  priority: 'low' | 'normal' | 'high' | 'urgent'
  assignee: string | null
  due_date: string | null
  assets: { name: string; url: string }[]
  notes: string | null
  created_at: string
}

const STAGES: { id: ProductionItem['stage']; label: string; color: string }[] = [
  { id: 'idea', label: 'Ideasi', color: 'bg-neutral-500/10 border-neutral-500/30 text-neutral-700 dark:text-neutral-300' },
  { id: 'script', label: 'Script / Brief', color: 'bg-blue-500/10 border-blue-500/30 text-blue-700 dark:text-blue-300' },
  { id: 'shooting', label: 'Shooting', color: 'bg-purple-500/10 border-purple-500/30 text-purple-700 dark:text-purple-300' },
  { id: 'editing', label: 'Editing', color: 'bg-indigo-500/10 border-indigo-500/30 text-indigo-700 dark:text-indigo-300' },
  { id: 'design', label: 'Design', color: 'bg-pink-500/10 border-pink-500/30 text-pink-700 dark:text-pink-300' },
  { id: 'caption', label: 'Caption', color: 'bg-emerald-500/10 border-emerald-500/30 text-emerald-700 dark:text-emerald-300' },
  { id: 'review', label: 'Review', color: 'bg-orange-500/10 border-orange-500/30 text-orange-700 dark:text-orange-300' },
  { id: 'ready', label: 'Siap Post', color: 'bg-green-500/10 border-green-500/30 text-green-700 dark:text-green-300' },
]

const AI_CAPABLE_STAGES = ['idea', 'script', 'editing', 'design', 'caption', 'review', 'ready']

export function ContentProductionBoard({ clientId }: { clientId: string }) {
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingItem, setEditingItem] = useState<ProductionItem | null>(null)
  const [defaultStage, setDefaultStage] = useState<ProductionItem['stage']>('idea')

  const [calendarOpen, setCalendarOpen] = useState(false)
  const [calendarItem, setCalendarItem] = useState<ProductionItem | null>(null)

  const [isGenerating, setIsGenerating] = useState(false)
  const [generateModalOpen, setGenerateModalOpen] = useState(false)
  const [genTopic, setGenTopic] = useState('')
  const [genAssetCount, setGenAssetCount] = useState(2)
  const [genPlatforms, setGenPlatforms] = useState<string[]>(['INSTAGRAM', 'TIKTOK', 'FACEBOOK'])

  // AI task generation state
  const [aiTaskModalOpen, setAiTaskModalOpen] = useState(false)
  const [selectedTask, setSelectedTask] = useState<ProductionItem | null>(null)
  const [selectedSkillIds, setSelectedSkillIds] = useState<string[]>([])
  const [availableSkills, setAvailableSkills] = useState<{ id: string; name: string }[]>([])
  const [isTaskGenerating, setIsTaskGenerating] = useState(false)

  const supabase = createClient()
  const channelRef = useRef<RealtimeChannel | null>(null)
  const queryClient = useQueryClient()

  const { data: items = [], isLoading: loading } = useQuery(
    productionsQueryOptions(clientId)
  )

  // Fetch AI drafts for display
  const { data: drafts = [] } = useQuery({
    queryKey: ['ai-drafts', clientId],
    queryFn: async () => {
      const { data } = await supabase
        .from('skill_outputs')
        .select('id, skill_id, title, content, stage, created_at, production_id')
        .eq('client_id', clientId)
        .eq('status', 'draft')
        .order('created_at', { ascending: false })
      return data ?? []
    },
    refetchInterval: 5000,
  })

  // Fetch scheduled posts so we can badge tasks that already have a calendar entry.
  const { data: scheduledPosts = [] } = useQuery({
    queryKey: ['scheduled-posts-for-board', clientId],
    queryFn: async () => {
      const { data } = await supabase
        .from('scheduled_posts')
        .select('id, production_id')
        .eq('client_id', clientId)
        .not('production_id', 'is', null)
      return data ?? []
    },
  })

  const deleteMutation = useMutation(deleteProductionMutation)

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: productionKeys.list(clientId) })
  }

  const handleAutoGenerate = async () => {
    try {
      setIsGenerating(true)
      const res = await fetch(`/api/admin/clients/${clientId}/generate-campaign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ topic: genTopic, assetCount: genAssetCount, platforms: genPlatforms })
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal generate')
      toast.success('Berhasil membuat kampanye AI!')
      setGenerateModalOpen(false)
      invalidate()
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Gagal generate')
    } finally {
      setIsGenerating(false)
    }
  }

  // Task AI generation handler
  const handleTaskAiGenerate = async () => {
    if (!selectedTask || selectedSkillIds.length === 0) {
      toast.error('Pilih minimal satu skill')
      return
    }

    try {
      setIsTaskGenerating(true)
      const res = await fetch(`/api/admin/clients/${clientId}/tasks/${selectedTask.id}/ai-generate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ skill_ids: selectedSkillIds })
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Gagal generate')

      toast.success(`Berhasil generate ${json.ok_count}/${selectedSkillIds.length} skill`)
      setAiTaskModalOpen(false)
      setSelectedSkillIds([])
      invalidate()
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Gagal generate')
    } finally {
      setIsTaskGenerating(false)
    }
  }

  // Move task to next stage after approve
  const handleApproveDraft = async (draft: any) => {
    if (!selectedTask) return

    const stageOrder = ['idea', 'script', 'shooting', 'editing', 'design', 'caption', 'review', 'ready']
    const currentIndex = stageOrder.indexOf(selectedTask.stage)
    if (currentIndex < 0 || currentIndex >= stageOrder.length - 1) {
      toast.error('Task sudah di stage terakhir atau tidak valid')
      return
    }

    const nextStage = stageOrder[currentIndex + 1]

    try {
      const res = await fetch('/api/admin/content-productions', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: selectedTask.id,
          stage: nextStage,
          notes: selectedTask.notes 
            ? `${selectedTask.notes}\n\n--- AI Draft Applied ---\n${draft.content}`
            : draft.content
        })
      })

      if (!res.ok) throw new Error('Failed to update task')

      // Mark draft as applied
      await supabase.from('skill_outputs').update({ status: 'approved' }).eq('id', draft.id)

      toast.success(`Task dipindahkan ke ${nextStage}`)
      setAiTaskModalOpen(false)
      setSelectedTask(null)
      invalidate()
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Gagal approve')
    }
  }

  // Fetch skills assigned to THIS client (client_skills), filtered to the task's stage.
  // Querying the global `skills` table would offer every skill in the library (100+)
  // and would let a client with no foundation generate anyway.
  useEffect(() => {
    if (!aiTaskModalOpen || !selectedTask) return

    const stages = getTaskSkillStages(selectedTask.stage)
    if (stages.length === 0) {
      setAvailableSkills([])
      return
    }

    let cancelled = false

    supabase
      .from('client_skills')
      .select('skill_id, skills!inner(id, name, stage)')
      .eq('client_id', clientId)
      .in('skills.stage', stages)
      .then(({ data }) => {
        if (cancelled) return
        const mapped = (data ?? [])
          .map((row) => {
            const s = row.skills as unknown as { id: string; name: string; stage: string } | null
            return s ? { id: s.id, name: s.name } : null
          })
          .filter((s): s is { id: string; name: string } => s !== null)
        setAvailableSkills(mapped)
        if (mapped.length === 1) setSelectedSkillIds([mapped[0].id])
      })

    return () => {
      cancelled = true
    }
  }, [aiTaskModalOpen, selectedTask, clientId, supabase])

  useEffect(() => {
    channelRef.current = supabase
      .channel('content-productions-changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'content_productions' },
        (payload) => {
          const row = (payload.new ?? payload.old) as Record<string, unknown>
          if (row.client_id === clientId) {
            invalidate()
          }
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channelRef.current!)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clientId, supabase])

  const openNewModal = (stage?: ProductionItem['stage']) => {
    setEditingItem(null)
    setDefaultStage(stage || 'idea')
    setDialogOpen(true)
  }

  const openEditModal = (item: ProductionItem) => {
    setEditingItem(item)
    setDefaultStage(item.stage)
    setDialogOpen(true)
  }

  const openCalendar = (item: ProductionItem) => {
    setCalendarItem(item)
    setCalendarOpen(true)
  }

  // Derive a sensible default date for the scheduling dialog.
  const calendarInitialDate = (
    calendarItem?.due_date
      ? new Date(`${calendarItem.due_date}T00:00:00`)
      : undefined
  ) ?? new Date()


  const handleDelete = async (id: string) => {
    if (!confirm('Hapus task produksi ini?')) return
    try {
      await deleteMutation.mutateAsync(id)
      toast.success('Task produksi dihapus')
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Gagal menghapus')
    }
  }

  const getDraftsForTask = (taskId: string) => 
    (drafts as any[]).filter(d => d.production_id === taskId)

  const isScheduled = (taskId: string) => 
    scheduledPosts.some((p) => p.production_id === taskId)

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold tracking-tight">Content Production Pipeline</h3>
          <p className="text-xs text-muted-foreground">
            Kelola produksi dari ide, shooting, editing, hingga siap post dalam satu board Kanban.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button onClick={() => setGenerateModalOpen(true)} size="sm" variant="secondary">
            <Icons.sparkles className="mr-2 h-4 w-4" />
            Generate Kampanye AI
          </Button>
          <Button onClick={() => openNewModal()} size="sm">
            + Task Produksi
          </Button>
        </div>
      </div>

      {loading ? (
        <div role="status" aria-live="polite" className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4 pb-4">
          <span className="sr-only">Memuat board produksi…</span>
          {STAGES.map((col) => (
            <div
              key={col.id}
              className="bg-muted/20 border rounded-xl p-3 flex flex-col gap-2.5"
              aria-hidden="true"
            >
              <div className="flex items-center justify-between pb-3 border-b">
                <Skeleton className="h-5 w-20 rounded" />
                <Skeleton className="h-5 w-6 rounded" />
              </div>
              {Array.from({ length: 2 }).map((_, i) => (
                <Skeleton key={i} className="h-24 rounded-lg" />
              ))}
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4 overflow-x-auto pb-4">
          {STAGES.map((col) => {
            const colItems = items.filter((i) => i.stage === col.id)
            return (
              <div key={col.id} className="bg-muted/20 border rounded-xl p-3 flex flex-col min-h-[450px]">
                <div className="flex items-center justify-between pb-3 border-b mb-3">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold px-2 py-0.5 rounded border bg-card">
                      {col.label}
                    </span>
                    <span className="text-xs font-bold text-muted-foreground">
                      {colItems.length}
                    </span>
                  </div>
                  <button
                    onClick={() => openNewModal(col.id as ProductionItem['stage'])}
                    className="flex size-9 items-center justify-center rounded-lg text-sm text-muted-foreground hover:bg-muted hover:text-foreground"
                    aria-label={`Tambah task baru di ${col.label}`}
                  >
                    <Icons.add className="size-4" aria-hidden="true" />
                  </button>
                </div>

                <div className="space-y-2.5 flex-1">
                  {colItems.map((item) => {
                    const taskDrafts = getDraftsForTask(item.id)
                    const hasReview = taskDrafts.length > 0
                    const canUseAI = AI_CAPABLE_STAGES.includes(item.stage)

                    return (
                      <button
                        key={item.id}
                        onClick={() => openEditModal(item)}
                        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') openEditModal(item) }}
                        className="w-full p-3 bg-card rounded-lg border shadow-sm hover:border-primary/50 transition-all text-left cursor-pointer space-y-2 group"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-1.5">
                            <PlatformIcon platform={item.platform} className="size-3.5" aria-hidden="true" />
                            <span className="text-[10px] uppercase font-bold text-muted-foreground">
                              {item.platform}
                            </span>
                          </div>
                          {item.priority !== 'normal' && (
                            <span
                              className={`text-[9px] font-bold uppercase px-1 rounded ${
                                item.priority === 'urgent'
                                  ? 'bg-red-500 text-white'
                                  : item.priority === 'high'
                                  ? 'bg-amber-500 text-white'
                                  : 'bg-blue-500 text-white'
                              }`}
                            >
                              {item.priority}
                            </span>
                          )}
                        </div>

                        <h4 className="text-xs font-semibold leading-snug group-hover:text-primary transition-colors">
                          {item.title}
                        </h4>

                        <div className="flex items-center justify-between text-[10px] text-muted-foreground pt-1 border-t">
                          <span>{item.assignee ? item.assignee : 'Unassigned'}</span>
                          {item.assets?.length > 0 && (
                            <span className="text-primary font-medium">
                              {item.assets.length} asset
                            </span>
                          )}
                        </div>

                        {/* AI Review Badge */}
                        {hasReview && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="w-full mt-1 text-xs h-7 border-dashed border-green-500/30 bg-green-500/10 text-green-700 hover:bg-green-500/20"
                            onClick={(e) => {
                              e.stopPropagation()
                              setSelectedTask(item)
                              setAiTaskModalOpen(true)
                            }}
                          >
                            <Icons.circleCheck className="mr-1 h-3 w-3" />
                            Review AI Draft ({taskDrafts.length})
                          </Button>
                        )}

                        {/* Schedule to Calendar button for "ready" stage */}
                        {item.stage === 'ready' && (
                          <Button
                            size="sm"
                            variant={isScheduled(item.id) ? 'outline' : 'secondary'}
                            className={`w-full h-11 sm:h-8 text-xs mt-2 ${
                              isScheduled(item.id)
                                ? 'border-primary/30 text-primary hover:bg-primary/5'
                                : ''
                            }`}
                            onClick={(e) => {
                              e.stopPropagation()
                              openCalendar(item)
                            }}
                          >
                            <Icons.calendar className="size-3.5 mr-1" aria-hidden="true" />
                            {isScheduled(item.id) ? 'Sudah dijadwalkan' : 'Jadwalkan ke Kalender'}
                          </Button>
                        )}

                        {/* AI Assist Button */}
                        {canUseAI && !hasReview && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="w-full h-7 text-xs text-purple-600 hover:text-purple-700 hover:bg-purple-50"
                            onClick={(e) => {
                              e.stopPropagation()
                              setSelectedTask(item)
                              setAiTaskModalOpen(true)
                            }}
                          >
                            <Icons.sparkles className="mr-1 h-3 w-3" />
                            Bantu AI
                          </Button>
                        )}
                      </button>
                    )
                  })}
                  {colItems.length === 0 && (
                    <div className="h-24 flex items-center justify-center border border-dashed rounded-lg text-[11px] text-muted-foreground">
                      Kosong
                    </div>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Edit / Create Modal */}
      <ContentFormModal
        clientId={clientId}
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        editingItem={editingItem}
        defaultStage={defaultStage}
        onSuccess={invalidate}
        onDelete={handleDelete}
      />

      <PostDialog
        isOpen={calendarOpen}
        onClose={() => setCalendarOpen(false)}
        clientId={clientId}
        onSave={() => { invalidate(); setCalendarItem(null); }}
        initialTitle={calendarItem?.title}
        initialContent={calendarItem?.notes || ''}
        initialDate={calendarInitialDate}
        productionId={calendarItem?.id}
      />

      {/* Generate Campaign Modal */}
      <Dialog open={generateModalOpen} onOpenChange={setGenerateModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Generate Campaign</DialogTitle>
            <DialogDescription>
              AI akan membuat kampanye dan draft aset berdasarkan Brand Profile klien.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label htmlFor="gen-topic">Topik Spesifik (Opsional)</Label>
              <Textarea 
                id="gen-topic"
                placeholder="Contoh: Fokus ke promo diskon akhir tahun..."
                value={genTopic}
                onChange={(e) => setGenTopic(e.target.value)}
                className="resize-none h-20 text-sm"
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="gen-asset-count">Jumlah Ide Aset</Label>
              <select 
                id="gen-asset-count"
                className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                value={genAssetCount} 
                onChange={(e) => setGenAssetCount(Number(e.target.value))}
              >
                <option value={1}>1 Ide Konten</option>
                <option value={2}>2 Ide Konten</option>
                <option value={3}>3 Ide Konten</option>
                <option value={4}>4 Ide Konten</option>
                <option value={5}>5 Ide Konten</option>
              </select>
            </div>
            <div className="space-y-2">
              <Label>Platform Target</Label>
              <fieldset className="grid grid-cols-2 gap-2 text-sm">
                <legend className="sr-only">Pilih platform target</legend>
                {['INSTAGRAM', 'TIKTOK', 'FACEBOOK', 'LINKEDIN', 'YOUTUBE', 'TWITTER'].map(p => (
                  <label key={p} htmlFor={`gen-platform-${p}`} className="flex items-center gap-2 cursor-pointer border rounded p-2 hover:bg-muted/50 min-h-[44px]">
                    <input 
                      id={`gen-platform-${p}`}
                      type="checkbox" 
                      checked={genPlatforms.includes(p)}
                      onChange={(e) => {
                        if (e.target.checked) setGenPlatforms([...genPlatforms, p])
                        else setGenPlatforms(genPlatforms.filter(x => x !== p))
                      }}
                    />
                    <span>{p}</span>
                  </label>
                ))}
              </fieldset>
            </div>
            <Button onClick={handleAutoGenerate} disabled={isGenerating} className="w-full mt-4">
              {isGenerating && <Icons.spinner className="size-4 mr-2 animate-spin" />}
              Mulai Generate
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Task AI Generation Modal */}
      <Dialog open={aiTaskModalOpen} onOpenChange={setAiTaskModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {selectedTask ? `Bantu AI - ${selectedTask.title}` : 'AI Assistant'}
            </DialogTitle>
            <DialogDescription>
              Pilih skill untuk membantu menyelesaikan task ini. Output akan disimpan sebagai draft untuk review.
            </DialogDescription>
          </DialogHeader>

          {selectedTask && (
            <div className="space-y-4 py-4">
              {/* Task Info */}
              <div className="grid grid-cols-2 gap-4 text-sm bg-muted p-3 rounded-lg">
                <div>
                  <span className="text-muted-foreground">Platform:</span>
                  <span className="ml-2 capitalize font-medium">{selectedTask.platform}</span>
                </div>
                <div>
                  <span className="text-muted-foreground">Stage:</span>
                  <span className="ml-2 font-medium">{selectedTask.stage}</span>
                </div>
                {selectedTask.notes && (
                  <div className="col-span-2">
                    <span className="text-muted-foreground">Notes:</span>
                    <p className="mt-1 text-xs bg-background p-2 rounded border">{selectedTask.notes}</p>
                  </div>
                )}
              </div>

              {/* Skill Selection */}
              {availableSkills.length > 0 ? (
                <div className="space-y-2">
                  <Label>Pilih Skill</Label>
                  <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto border rounded-lg p-3">
                    {availableSkills.map((skill) => (
                      <Button
                        key={skill.id}
                        variant={selectedSkillIds.includes(skill.id) ? 'default' : 'outline'}
                        size="sm"
                        className="text-xs justify-start h-10"
                        onClick={() => {
                          setSelectedSkillIds(prev =>
                            prev.includes(skill.id)
                              ? prev.filter(x => x !== skill.id)
                              : [...prev, skill.id]
                          )
                        }}
                      >
                        {skill.name}
                      </Button>
                    ))}
                  </div>
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Tidak ada skill yang tersedia untuk stage ini.
                </p>
              )}

              {/* Existing Drafts */}
              {getDraftsForTask(selectedTask.id).length > 0 && (
                <div className="space-y-2">
                  <Label>Draft Tersedia</Label>
                  <div className="border rounded-lg p-3 space-y-3 max-h-48 overflow-y-auto">
                    {getDraftsForTask(selectedTask.id).map((draft) => (
                      <div key={draft.id} className="border rounded p-3 text-xs space-y-2 bg-muted/30">
                        <div className="flex items-center justify-between">
                          <span className="font-medium">{draft.skill_id}</span>
                          <span className="text-muted-foreground">{new Date(draft.created_at).toLocaleString('id-ID')}</span>
                        </div>
                        <div className="text-muted-foreground line-clamp-3">{draft.content}</div>
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            variant="default"
                            className="text-xs h-7"
                            onClick={() => handleApproveDraft(draft)}
                          >
                            <Icons.check className="mr-1 h-3 w-3" />
                            Approve & Continue
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setAiTaskModalOpen(false)}>
              Batal
            </Button>
            <Button
              onClick={handleTaskAiGenerate}
              disabled={isTaskGenerating || selectedSkillIds.length === 0}
            >
              {isTaskGenerating ? (
                <Icons.spinner className="mr-2 h-4 w-4 animate-spin" />
              ) : null}
              Generate AI
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

// @ts-nocheck
'use client';

import {
  type Announcements,
  type CollisionDetection,
  closestCenter,
  closestCorners,
  DndContext,
  type DndContextProps,
  type DragCancelEvent,
  type DragEndEvent,
  type DraggableAttributes,
  type DraggableSyntheticListeners,
  type DragOverEvent,
  DragOverlay,
  type DragStartEvent,
  type DropAnimation,
  type DroppableContainer,
  defaultDropAnimationSideEffects,
  getFirstCollision,
  KeyboardCode,
  type KeyboardCoordinateGetter,
  KeyboardSensor,
  MeasuringStrategy,
  MouseSensor,
  pointerWithin,
  rectIntersection,
  TouchSensor,
  type UniqueIdentifier,
  useSensor,
  useSensors
} from '@dnd-kit/core';
import {
  type AnimateLayoutChanges,
  arrayMove,
  defaultAnimateLayoutChanges,
  horizontalListSortingStrategy,
  SortableContext,
  type SortableContextProps,
  useSortable,
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';
import * as ReactDOM from 'react-dom';

import { useComposedRefs } from '@/lib/compose-refs';
import { cn } from '@/lib/utils';

const directions: string[] = [
  KeyboardCode.Down,
  KeyboardCode.Right,
  KeyboardCode.Up,
  KeyboardCode.Left
];

const coordinateGetter: KeyboardCoordinateGetter = (event, { context }) => {
  const { active, droppableRects, droppableContainers, collisionRect } = context;

  if (directions.includes(event.code)) {
    event.preventDefault();

    if (!active || !collisionRect) return;

    const filteredContainers: DroppableContainer[] = [];

    for (const entry of droppableContainers.getEnabled()) {
      if (!entry || entry?.disabled) return;

      const rect = droppableRects.get(entry.id);

      if (!rect) return;

      const data = entry.data.current;

      if (data) {
        const { type, children } = data;

        if (type === 'container' && children?.length > 0) {
          if (active.data.current?.type !== 'container') {
            return;
          }
        }
      }

      switch (event.code) {
        case KeyboardCode.Down:
          if (collisionRect.top < rect.top) {
            filteredContainers.push(entry);
          }
          break;
        case KeyboardCode.Up:
          if (collisionRect.top > rect.top) {
            filteredContainers.push(entry);
          }
          break;
        case KeyboardCode.Left:
          if (collisionRect.left >= rect.left + rect.width) {
            filteredContainers.push(entry);
          }
          break;
        case KeyboardCode.Right:
          if (collisionRect.left + collisionRect.width <= rect.left) {
            filteredContainers.push(entry);
          }
          break;
      }
    }

    const collisions = closestCorners({
      active,
      collisionRect: collisionRect,
      droppableRects,
      droppableContainers: filteredContainers,
      pointerCoordinates: null
    });
    const closestId = getFirstCollision(collisions, 'id');

    if (closestId != null) {
      const newDroppable = droppableContainers.get(closestId);
      const newNode = newDroppable?.node.current;
      const newRect = newDroppable?.rect.current;

      if (newNode && newRect) {
        if (newDroppable.id === 'placeholder') {
          return {
            x: newRect.left + (newRect.width - collisionRect.width) / 2,
            y: newRect.top + (newRect.height - collisionRect.height) / 2
          };
        }

        if (newDroppable.data.current?.type === 'container') {
          return {
            x: newRect.left + 20,
            y: newRect.top + 74
          };
        }

        return {
          x: newRect.left,
          y: newRect.top
        };
      }
    }
  }

  return undefined;
};

const ROOT_NAME = 'Kanban';
const BOARD_NAME = 'KanbanBoard';
const COLUMN_NAME = 'KanbanColumn';
const COLUMN_HANDLE_NAME = 'KanbanColumnHandle';
const ITEM_NAME = 'KanbanItem';
const ITEM_HANDLE_NAME = 'KanbanItemHandle';
const OVERLAY_NAME = 'KanbanOverlay';

interface KanbanContextValue<T> {
  id: string;
  items: Record<UniqueIdentifier, T[]>;
  modifiers: DndContextProps['modifiers'];
  strategy: SortableContextProps['strategy'];
  orientation: 'horizontal' | 'vertical';
  activeId: UniqueIdentifier | null;
  setActiveId: (id: UniqueIdentifier | null) => void;
  getItemValue: (item: T) => UniqueIdentifier;
  flatCursor: boolean;
}

const KanbanContext = React.createContext<KanbanContextValue<unknown> | null>(null);

function useKanbanContext(consumerName: string) {
  const context = React.useContext(KanbanContext);
  if (!context) {
    throw new Error(`\`${consumerName}\` must be used within \`${ROOT_NAME}\``);
  }
  return context;
}

interface GetItemValue<T> {
  /**
   * Callback that returns a unique identifier for each kanban item. Required for array of objects.
   * @example getItemValue={(item) => item.id}
   */
  getItemValue: (item: T) => UniqueIdentifier;
}

type KanbanProps<T> = Omit<DndContextProps, 'collisionDetection'> &
  (T extends object ? GetItemValue<T> : Partial<GetItemValue<T>>) & {
    value: Record<UniqueIdentifier, T[]>;
    onValueChange?: (columns: Record<UniqueIdentifier, T[]>) => void;
    onMove?: (event: DragEndEvent & { activeIndex: number; overIndex: number }) => void;
    strategy?: SortableContextProps['strategy'];
    orientation?: 'horizontal' | 'vertical';
    flatCursor?: boolean;
  };

function Kanban<T>(props: KanbanProps<T>) {
  const {
    value,
    onValueChange,
    modifiers,
    strategy = verticalListSortingStrategy,
    orientation = 'horizontal',
    onMove,
    getItemValue: getItemValueProp,
    accessibility,
    flatCursor = false,
    ...kanbanProps
  } = props;

  const id = React.useId();
  const [activeId, setActiveId] = React.useState<UniqueIdentifier | null>(null);
  const lastOverIdRef = React.useRef<UniqueIdentifier | null>(null);
  const hasMovedRef = React.useRef(false);
  const sensors = useSensors(
    useSensor(MouseSensor),
    useSensor(TouchSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter
    })
  );

  const getItemValue = React.useCallback(
    (item: T): UniqueIdentifier => {
      if (typeof item === 'object' && !getItemValueProp) {
        throw new Error('`getItemValue` is required when using array of objects');
      }
      return getItemValueProp ? getItemValueProp(item) : (item as UniqueIdentifier);
    },
    [getItemValueProp]
  );

  const getColumn = React.useCallback(
    (id: UniqueIdentifier) => {
      if (id in value) return id;

      for (const [columnId, items] of Object.entries(value)) {
        if (items.some((item) => getItemValue(item) === id)) {
          return columnId;
        }
      }

      return null;
    },
    [value, getItemValue]
  );

  const collisionDetection: CollisionDetection = React.useCallback(
    (args) => {
      if (activeId && activeId in value) {
        return closestCenter({
          ...args,
          droppableContainers: args.droppableContainers.filter((container) => container.id in value)
        });
      }

      const pointerIntersections = pointerWithin(args);
      const intersections =
        pointerIntersections.length > 0 ? pointerIntersections : rectIntersection(args);
      let overId = getFirstCollision(intersections, 'id');

      if (!overId) {
        if (hasMovedRef.current) {
          lastOverIdRef.current = activeId;
        }
        return lastOverIdRef.current ? [{ id: lastOverIdRef.current }] : [];
      }

      if (overId in value) {
        const containerItems = value[overId];
        if (containerItems && containerItems.length > 0) {
          const closestItem = closestCenter({
            ...args,
            droppableContainers: args.droppableContainers.filter(
              (container) =>
                container.id !== overId &&
                containerItems.some((item) => getItemValue(item) === container.id)
            )
          });

          if (closestItem.length > 0) {
            overId = closestItem[0]?.id ?? overId;
          }
        }
      }

      lastOverIdRef.current = overId;
      return [{ id: overId }];
    },
    [activeId, value, getItemValue]
  );

  const onDragStart = React.useCallback(
    (event: DragStartEvent) => {
      kanbanProps.onDragStart?.(event);

      if (event.activatorEvent.defaultPrevented) return;
      setActiveId(event.active.id);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- kanbanProps is unstable object ref, using specific prop
    [kanbanProps.onDragStart]
  );

  const onDragOver = React.useCallback(
    (event: DragOverEvent) => {
      kanbanProps.onDragOver?.(event);

      if (event.activatorEvent.defaultPrevented) return;

      const { active, over } = event;
      if (!over) return;

      const activeColumn = getColumn(active.id);
      const overColumn = getColumn(over.id);

      if (!activeColumn || !overColumn) return;

      if (activeColumn === overColumn) {
        const items = value[activeColumn];
        if (!items) return;

        const activeIndex = items.findIndex((item) => getItemValue(item) === active.id);
        const overIndex = items.findIndex((item) => getItemValue(item) === over.id);

        if (activeIndex !== overIndex) {
          const newColumns = { ...value };
          newColumns[activeColumn] = arrayMove(items, activeIndex, overIndex);
          onValueChange?.(newColumns);
        }
      } else {
        const activeItems = value[activeColumn];
        const overItems = value[overColumn];

        if (!activeItems || !overItems) return;

        const activeIndex = activeItems.findIndex((item) => getItemValue(item) === active.id);

        if (activeIndex === -1) return;

        const activeItem = activeItems[activeIndex];
        if (!activeItem) return;

        const updatedItems = {
          ...value,
          [activeColumn]: activeItems.filter((item) => getItemValue(item) !== active.id),
          [overColumn]: [...overItems, activeItem]
        };

        onValueChange?.(updatedItems);
        hasMovedRef.current = true;
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- kanbanProps is unstable object ref, using specific prop
    [value, getColumn, getItemValue, onValueChange, kanbanProps.onDragOver]
  );

  const onDragEnd = React.useCallback(
    (event: DragEndEvent) => {
      kanbanProps.onDragEnd?.(event);

      if (event.activatorEvent.defaultPrevented) return;

      const { active, over } = event;

      if (!over) {
        setActiveId(null);
        return;
      }

      if (active.id in value && over.id in value) {
        const activeIndex = Object.keys(value).indexOf(active.id as string);
        const overIndex = Object.keys(value).indexOf(over.id as string);

        if (activeIndex !== overIndex) {
          const orderedColumns = Object.keys(value);
          const newOrder = arrayMove(orderedColumns, activeIndex, overIndex);

          const newColumns: Record<UniqueIdentifier, T[]> = {};
          for (const key of newOrder) {
            const items = value[key];
            if (items) {
              newColumns[key] = items;
            }
          }

          if (onMove) {
            onMove({ ...event, activeIndex, overIndex });
          } else {
            onValueChange?.(newColumns);
          }
        }
      } else {
        const activeColumn = getColumn(active.id);
        const overColumn = getColumn(over.id);

        if (!activeColumn || !overColumn) {
          setActiveId(null);
          return;
        }

        if (activeColumn === overColumn) {
          const items = value[activeColumn];
          if (!items) {
            setActiveId(null);
            return;
          }

          const activeIndex = items.findIndex((item) => getItemValue(item) === active.id);
          const overIndex = items.findIndex((item) => getItemValue(item) === over.id);

          if (activeIndex !== overIndex) {
            const newColumns = { ...value };
            newColumns[activeColumn] = arrayMove(items, activeIndex, overIndex);
            if (onMove) {
              onMove({
                ...event,
                activeIndex,
                overIndex
              });
            } else {
              onValueChange?.(newColumns);
            }
          }
        }
      }

      setActiveId(null);
      hasMovedRef.current = false;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- kanbanProps is unstable object ref, using specific prop
    [value, getColumn, getItemValue, onValueChange, onMove, kanbanProps.onDragEnd]
  );

  const onDragCancel = React.useCallback(
    (event: DragCancelEvent) => {
      kanbanProps.onDragCancel?.(event);

      if (event.activatorEvent.defaultPrevented) return;

      setActiveId(null);
      hasMovedRef.current = false;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- kanbanProps is unstable object ref, using specific prop
    [kanbanProps.onDragCancel]
  );

  const announcements: Announcements = React.useMemo(
    () => ({
      onDragStart({ active }) {
        const isColumn = active.id in value;
        const itemType = isColumn ? 'column' : 'item';
        const position = isColumn
          ? Object.keys(value).indexOf(active.id as string) + 1
          : (() => {
              const column = getColumn(active.id);
              if (!column || !value[column]) return 1;
              return value[column].findIndex((item) => getItemValue(item) === active.id) + 1;
            })();
        const total = isColumn
          ? Object.keys(value).length
          : (() => {
              const column = getColumn(active.id);
              return column ? (value[column]?.length ?? 0) : 0;
            })();

        return `Picked up ${itemType} at position ${position} of ${total}`;
      },
      onDragOver({ active, over }) {
        if (!over) return;

        const isColumn = active.id in value;
        const itemType = isColumn ? 'column' : 'item';
        const position = isColumn
          ? Object.keys(value).indexOf(over.id as string) + 1
          : (() => {
              const column = getColumn(over.id);
              if (!column || !value[column]) return 1;
              return value[column].findIndex((item) => getItemValue(item) === over.id) + 1;
            })();
        const total = isColumn
          ? Object.keys(value).length
          : (() => {
              const column = getColumn(over.id);
              return column ? (value[column]?.length ?? 0) : 0;
            })();

        const overColumn = getColumn(over.id);
        const activeColumn = getColumn(active.id);

        if (isColumn) {
          return `${itemType} is now at position ${position} of ${total}`;
        }

        if (activeColumn !== overColumn) {
          return `${itemType} is now at position ${position} of ${total} in ${overColumn}`;
        }

        return `${itemType} is now at position ${position} of ${total}`;
      },
      onDragEnd({ active, over }) {
        if (!over) return;

        const isColumn = active.id in value;
        const itemType = isColumn ? 'column' : 'item';
        const position = isColumn
          ? Object.keys(value).indexOf(over.id as string) + 1
          : (() => {
              const column = getColumn(over.id);
              if (!column || !value[column]) return 1;
              return value[column].findIndex((item) => getItemValue(item) === over.id) + 1;
            })();
        const total = isColumn
          ? Object.keys(value).length
          : (() => {
              const column = getColumn(over.id);
              return column ? (value[column]?.length ?? 0) : 0;
            })();

        const overColumn = getColumn(over.id);
        const activeColumn = getColumn(active.id);

        if (isColumn) {
          return `${itemType} was dropped at position ${position} of ${total}`;
        }

        if (activeColumn !== overColumn) {
          return `${itemType} was dropped at position ${position} of ${total} in ${overColumn}`;
        }

        return `${itemType} was dropped at position ${position} of ${total}`;
      },
      onDragCancel({ active }) {
        const isColumn = active.id in value;
        const itemType = isColumn ? 'column' : 'item';
        return `Dragging was cancelled. ${itemType} was dropped.`;
      }
    }),
    [value, getColumn, getItemValue]
  );

  const contextValue = React.useMemo<KanbanContextValue<T>>(
    () => ({
      id,
      items: value,
      modifiers,
      strategy,
      orientation,
      activeId,
      setActiveId,
      getItemValue,
      flatCursor
    }),
    [id, value, activeId, modifiers, strategy, orientation, getItemValue, flatCursor]
  );

  return (
    <KanbanContext.Provider value={contextValue as KanbanContextValue<unknown>}>
      <DndContext
        collisionDetection={collisionDetection}
        modifiers={modifiers}
        sensors={sensors}
        {...kanbanProps}
        id={id}
        measuring={{
          droppable: {
            strategy: MeasuringStrategy.Always
          }
        }}
        onDragStart={onDragStart}
        onDragOver={onDragOver}
        onDragEnd={onDragEnd}
        onDragCancel={onDragCancel}
        accessibility={{
          announcements,
          screenReaderInstructions: {
            draggable: `
            To pick up a kanban item or column, press space or enter.
            While dragging, use the arrow keys to move the item.
            Press space or enter again to drop the item in its new position, or press escape to cancel.
          `
          },
          ...accessibility
        }}
      />
    </KanbanContext.Provider>
  );
}

const KanbanBoardContext = React.createContext<boolean>(false);

interface KanbanBoardProps extends React.ComponentProps<'div'> {
  children: React.ReactNode;
  render?: useRender.RenderProp;
}

function KanbanBoard(props: KanbanBoardProps) {
  const { render, className, ref, ...boardProps } = props;

  const context = useKanbanContext(BOARD_NAME);

  const columns = React.useMemo(() => {
    return Object.keys(context.items);
  }, [context.items]);

  const board = useRender({
    defaultTagName: 'div',
    render,
    ref,
    props: mergeProps<'div'>(
      {
        'aria-orientation': context.orientation,
        'data-orientation': context.orientation,
        'data-slot': 'kanban-board'
      } as React.ComponentProps<'div'>,
      boardProps,
      {
        className: cn(
          'flex size-full gap-4',
          context.orientation === 'horizontal' ? 'flex-row' : 'flex-col',
          className
        )
      }
    )
  });

  return (
    <KanbanBoardContext.Provider value={true}>
      <SortableContext
        items={columns}
        strategy={
          context.orientation === 'horizontal'
            ? horizontalListSortingStrategy
            : verticalListSortingStrategy
        }
      >
        {board}
      </SortableContext>
    </KanbanBoardContext.Provider>
  );
}

interface KanbanColumnContextValue {
  id: string;
  attributes: DraggableAttributes;
  listeners: DraggableSyntheticListeners | undefined;
  setActivatorNodeRef: (node: HTMLElement | null) => void;
  isDragging?: boolean;
  disabled?: boolean;
}

const KanbanColumnContext = React.createContext<KanbanColumnContextValue | null>(null);

function useKanbanColumnContext(consumerName: string) {
  const context = React.useContext(KanbanColumnContext);
  if (!context) {
    throw new Error(`\`${consumerName}\` must be used within \`${COLUMN_NAME}\``);
  }
  return context;
}

const animateLayoutChanges: AnimateLayoutChanges = (args) =>
  defaultAnimateLayoutChanges({ ...args, wasDragging: true });

interface KanbanColumnProps extends React.ComponentProps<'div'> {
  value: UniqueIdentifier;
  children: React.ReactNode;
  render?: useRender.RenderProp;
  asHandle?: boolean;
  disabled?: boolean;
}

function KanbanColumn(props: KanbanColumnProps) {
  const { value, render, asHandle, disabled, className, style, ref, ...columnProps } = props;

  const id = React.useId();
  const context = useKanbanContext(COLUMN_NAME);
  const inBoard = React.useContext(KanbanBoardContext);
  const inOverlay = React.useContext(KanbanOverlayContext);

  if (!inBoard && !inOverlay) {
    throw new Error(
      `\`${COLUMN_NAME}\` must be used within \`${BOARD_NAME}\` or \`${OVERLAY_NAME}\``
    );
  }

  if (value === '') {
    throw new Error(`\`${COLUMN_NAME}\` value cannot be an empty string`);
  }

  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({
    id: value,
    disabled,
    animateLayoutChanges
  });

  const composedRef = useComposedRefs(ref, (node) => {
    if (disabled) return;
    setNodeRef(node);
  });

  const composedStyle = React.useMemo<React.CSSProperties>(() => {
    return {
      transform: CSS.Transform.toString(transform),
      transition,
      ...style
    };
  }, [transform, transition, style]);

  const items = React.useMemo(() => {
    const items = context.items[value] ?? [];
    return items.map((item) => context.getItemValue(item));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- context is unstable object ref, using specific properties
  }, [context.items, value, context.getItemValue]);

  const columnContext = React.useMemo<KanbanColumnContextValue>(
    () => ({
      id,
      attributes,
      listeners,
      setActivatorNodeRef,
      isDragging,
      disabled
    }),
    [id, attributes, listeners, setActivatorNodeRef, isDragging, disabled]
  );

  const column = useRender({
    defaultTagName: 'div',
    render,
    ref: composedRef,
    props: mergeProps<'div'>(
      {
        id,
        'data-disabled': disabled,
        'data-dragging': isDragging ? '' : undefined,
        'data-slot': 'kanban-column'
      } as React.ComponentProps<'div'>,
      columnProps,
      asHandle && !disabled ? { ...attributes, ...listeners } : {},
      {
        style: composedStyle,
        className: cn(
          'flex size-full flex-col gap-2 rounded-lg border bg-zinc-100 p-2.5 aria-disabled:pointer-events-none aria-disabled:opacity-50 dark:bg-zinc-900',
          {
            'touch-none select-none': asHandle,
            'cursor-default': context.flatCursor,
            'data-dragging:cursor-grabbing': !context.flatCursor,
            'cursor-grab': !isDragging && asHandle && !context.flatCursor,
            'opacity-50': isDragging,
            'pointer-events-none opacity-50': disabled
          },
          className
        )
      }
    )
  });

  return (
    <KanbanColumnContext.Provider value={columnContext}>
      <SortableContext
        items={items}
        strategy={
          context.orientation === 'horizontal'
            ? horizontalListSortingStrategy
            : verticalListSortingStrategy
        }
      >
        {column}
      </SortableContext>
    </KanbanColumnContext.Provider>
  );
}

interface KanbanColumnHandleProps extends React.ComponentProps<'button'> {
  render?: useRender.RenderProp;
}

function KanbanColumnHandle(props: KanbanColumnHandleProps) {
  const { render, disabled, className, ref, ...columnHandleProps } = props;

  const context = useKanbanContext(COLUMN_NAME);
  const columnContext = useKanbanColumnContext(COLUMN_HANDLE_NAME);

  const isDisabled = disabled ?? columnContext.disabled;

  const composedRef = useComposedRefs(ref, (node) => {
    if (isDisabled) return;
    columnContext.setActivatorNodeRef(node);
  });

  return useRender({
    defaultTagName: 'button',
    render,
    ref: composedRef,
    props: mergeProps<'button'>(
      {
        type: 'button',
        'aria-controls': columnContext.id,
        'data-disabled': isDisabled,
        'data-dragging': columnContext.isDragging ? '' : undefined,
        'data-slot': 'kanban-column-handle'
      } as React.ComponentProps<'button'>,
      columnHandleProps,
      isDisabled ? {} : { ...columnContext.attributes, ...columnContext.listeners },
      {
        className: cn(
          'select-none disabled:pointer-events-none disabled:opacity-50',
          context.flatCursor ? 'cursor-default' : 'cursor-grab data-dragging:cursor-grabbing',
          className
        ),
        disabled: isDisabled
      }
    )
  });
}

interface KanbanItemContextValue {
  id: string;
  attributes: DraggableAttributes;
  listeners: DraggableSyntheticListeners | undefined;
  setActivatorNodeRef: (node: HTMLElement | null) => void;
  isDragging?: boolean;
  disabled?: boolean;
}

const KanbanItemContext = React.createContext<KanbanItemContextValue | null>(null);

function useKanbanItemContext(consumerName: string) {
  const context = React.useContext(KanbanItemContext);
  if (!context) {
    throw new Error(`\`${consumerName}\` must be used within \`${ITEM_NAME}\``);
  }
  return context;
}

interface KanbanItemProps extends React.ComponentProps<'div'> {
  value: UniqueIdentifier;
  asHandle?: boolean;
  render?: useRender.RenderProp;
  disabled?: boolean;
}

function KanbanItem(props: KanbanItemProps) {
  const { value, style, asHandle, render, disabled, className, ref, ...itemProps } = props;

  const id = React.useId();
  const context = useKanbanContext(ITEM_NAME);
  const inBoard = React.useContext(KanbanBoardContext);
  const inOverlay = React.useContext(KanbanOverlayContext);

  if (!inBoard && !inOverlay) {
    throw new Error(`\`${ITEM_NAME}\` must be used within \`${BOARD_NAME}\``);
  }

  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: value, disabled });

  if (value === '') {
    throw new Error(`\`${ITEM_NAME}\` value cannot be an empty string`);
  }

  const composedRef = useComposedRefs(ref, (node) => {
    if (disabled) return;
    setNodeRef(node);
  });

  const composedStyle = React.useMemo<React.CSSProperties>(() => {
    return {
      transform: CSS.Transform.toString(transform),
      transition,
      ...style
    };
  }, [transform, transition, style]);

  const itemContext = React.useMemo<KanbanItemContextValue>(
    () => ({
      id,
      attributes,
      listeners,
      setActivatorNodeRef,
      isDragging,
      disabled
    }),
    [id, attributes, listeners, setActivatorNodeRef, isDragging, disabled]
  );

  const item = useRender({
    defaultTagName: 'div',
    render,
    ref: composedRef,
    props: mergeProps<'div'>(
      {
        id,
        'data-disabled': disabled,
        'data-dragging': isDragging ? '' : undefined,
        'data-slot': 'kanban-item'
      } as React.ComponentProps<'div'>,
      itemProps,
      asHandle && !disabled ? { ...attributes, ...listeners } : {},
      {
        style: composedStyle,
        className: cn(
          'focus-visible:ring-ring focus-visible:ring-1 focus-visible:ring-offset-1 focus-visible:outline-hidden',
          {
            'touch-none select-none': asHandle,
            'cursor-default': context.flatCursor,
            'data-dragging:cursor-grabbing': !context.flatCursor,
            'cursor-grab': !isDragging && asHandle && !context.flatCursor,
            'opacity-50': isDragging,
            'pointer-events-none opacity-50': disabled
          },
          className
        )
      }
    )
  });

  return <KanbanItemContext.Provider value={itemContext}>{item}</KanbanItemContext.Provider>;
}

interface KanbanItemHandleProps extends React.ComponentProps<'button'> {
  render?: useRender.RenderProp;
}

function KanbanItemHandle(props: KanbanItemHandleProps) {
  const { render, disabled, className, ref, ...itemHandleProps } = props;

  const context = useKanbanContext(ITEM_HANDLE_NAME);
  const itemContext = useKanbanItemContext(ITEM_HANDLE_NAME);

  const isDisabled = disabled ?? itemContext.disabled;

  const composedRef = useComposedRefs(ref, (node) => {
    if (isDisabled) return;
    itemContext.setActivatorNodeRef(node);
  });

  return useRender({
    defaultTagName: 'button',
    render,
    ref: composedRef,
    props: mergeProps<'button'>(
      {
        type: 'button',
        'aria-controls': itemContext.id,
        'data-disabled': isDisabled,
        'data-dragging': itemContext.isDragging ? '' : undefined,
        'data-slot': 'kanban-item-handle'
      } as React.ComponentProps<'button'>,
      itemHandleProps,
      isDisabled ? {} : { ...itemContext.attributes, ...itemContext.listeners },
      {
        className: cn(
          'select-none disabled:pointer-events-none disabled:opacity-50',
          context.flatCursor ? 'cursor-default' : 'cursor-grab data-dragging:cursor-grabbing',
          className
        ),
        disabled: isDisabled
      }
    )
  });
}

const KanbanOverlayContext = React.createContext(false);

const dropAnimation: DropAnimation = {
  sideEffects: defaultDropAnimationSideEffects({
    styles: {
      active: {
        opacity: '0.4'
      }
    }
  })
};

interface KanbanOverlayProps extends Omit<React.ComponentProps<typeof DragOverlay>, 'children'> {
  container?: Element | DocumentFragment | null;
  children?:
    | React.ReactNode
    | ((params: { value: UniqueIdentifier; variant: 'column' | 'item' }) => React.ReactNode);
}

function KanbanOverlay(props: KanbanOverlayProps) {
  const { container: containerProp, children, ...overlayProps } = props;

  const context = useKanbanContext(OVERLAY_NAME);

  const [mounted, setMounted] = React.useState(false);

  React.useLayoutEffect(() => setMounted(true), []);

  const container = containerProp ?? (mounted ? globalThis.document?.body : null);

  if (!container) return null;

  const variant = context.activeId && context.activeId in context.items ? 'column' : 'item';

  return ReactDOM.createPortal(
    <DragOverlay
      dropAnimation={dropAnimation}
      modifiers={context.modifiers}
      className={cn(!context.flatCursor && 'cursor-grabbing')}
      {...overlayProps}
    >
      <KanbanOverlayContext.Provider value={true}>
        {context.activeId && children
          ? typeof children === 'function'
            ? children({
                value: context.activeId,
                variant
              })
            : children
          : null}
      </KanbanOverlayContext.Provider>
    </DragOverlay>,
    container
  );
}

export {
  Kanban,
  KanbanBoard,
  KanbanColumn,
  KanbanColumnHandle,
  KanbanItem,
  KanbanItemHandle,
  KanbanOverlay,
  //
  type KanbanProps
};

"use client"

import { useMemo, useEffect } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { useQueryClient, useSuspenseQuery, useMutation } from "@tanstack/react-query"
import { z } from "zod"
import { useAppForm } from "@/lib/form"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Icons } from "@/components/icons"
import { toast } from "sonner"
import { createDeliverableMutation } from "../api/mutations"
import { clientsListQueryOptions } from "@/features/clients/api/queries"

const createSchema = z.object({
  title: z.string().min(1, "Judul wajib diisi"),
  client_id: z.string().min(1, "Pilih klien terlebih dahulu"),
  type: z.enum(["content", "brief", "report"] as const),
  content: z.string().optional(),
})

type CreateSchema = z.infer<typeof createSchema>

export function DeliverableNewForm() {
  const router = useRouter()
  const queryClient = useQueryClient()

  // Fetch data client list as options (page 1, perPage 100)
  const { data: clientsResponse } = useSuspenseQuery(
    clientsListQueryOptions({ page: 1, perPage: 100 })
  )

  const clientOptions = useMemo(
    () => clientsResponse.data.map((c) => ({ value: c.id, label: c.name })) ?? [],
    [clientsResponse.data]
  )

  const mutation = useMutation(createDeliverableMutation)

  // Admin deep-linking from a client workspace (?client=<id>) shouldn't have to re-pick it.
  const searchParams = useSearchParams()
  const preselectedClient = searchParams.get('client') ?? ''

  const form = useAppForm({
    defaultValues: {
      title: "",
      client_id: preselectedClient,
      type: "content",
      content: "",
    },
    onSubmit: async ({ value }) => {
      try {
        await mutation.mutateAsync(value as {
          title: string
          client_id: string
          type: "content" | "brief" | "report"
          content?: string
        })
        toast.success("Deliverable berhasil dibuat")
        router.push("/admin/deliverables")
      } catch {
        toast.error("Gagal membuat deliverable")
      }
    },
  })

  useEffect(() => {
    if (mutation.isSuccess) {
      queryClient.invalidateQueries({ queryKey: ["clients"] })
    }
  }, [mutation.isSuccess, queryClient])

  const handleCancel = () => router.push("/admin/deliverables")

  return (
    <div className="max-w-4xl mx-auto w-full space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Icons.page className="size-4 text-primary" />
            Informasi Dasar
          </CardTitle>
          <CardDescription className="text-xs">
            Buat draf konten, brief, atau laporan untuk brand klien.
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          <form.AppField
            name="title"
            children={(field) => (
              <field.TextField label="Judul Deliverable" required />
            )}
          />

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <form.AppField
              name="client_id"
              children={(field) => (
                <field.SelectField
                  label="Klien"
                  options={clientOptions}
                  required
                />
              )}
            />

            <form.AppField
              name="type"
              children={(field) => (
                <field.SelectField
                  label="Tipe Deliverable"
                  options={[
                    { value: "content", label: "Konten" },
                    { value: "brief", label: "Brief" },
                    { value: "report", label: "Laporan" },
                  ]}
                />
              )}
            />
          </div>

          <form.AppField
            name="content"
            children={(field) => (
              <field.TextareaField label="Isi Konten (Markdown didukung)" />
            )}
          />
        </CardContent>

        <CardFooter className="flex justify-end gap-3 border-t p-4 bg-muted/20">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleCancel}
            disabled={mutation.isPending}
          >
            Batal
          </Button>
          <form.Subscribe
            selector={(state) => [state.canSubmit, state.isSubmitting]}
            children={([canSubmit, isSubmitting]) => (
              <Button
                type="button"
                onClick={() => form.handleSubmit()}
                disabled={!canSubmit || mutation.isPending}
                isLoading={isSubmitting || mutation.isPending}
                className="bg-brand-accent hover:bg-brand-accent/90"
              >
                Simpan Deliverable
              </Button>
            )}
          />
        </CardFooter>
      </Card>
    </div>
  )
}

